/**
 * Asset Index Service - Maintains an index of all files for fast searching
 *
 * Storage: IndexedDB for large dataset support without RAM pressure
 * Data: Lean index storing only paths (filename/source derived at query time)
 *
 * Sync strategy:
 * 1. Build full index on world load (writes to IndexedDB)
 * 2. Monkey-patch getFilePicker().upload for immediate updates
 * 3. Background re-index every 5 minutes to catch external changes
 */

import { createLogger } from '../utils/logger.js';
import { emitIndexStatus } from './hook-manager.js';

const DB_NAME = 'simulacrum-asset-index';
const DB_VERSION = 2; // v2: added meta store for completion tracking
const PROGRESS_LOG_INTERVAL = 10000; // Log progress every N files
const STALENESS_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
const HEARTBEAT_INTERVAL_MS = 10 * 1000; // 10 seconds

// Roots that map to 'public' source, everything else is 'data'
const PUBLIC_ROOTS = ['icons', 'sounds'];

/**
 * Get the FilePicker class (handles v13+ namespacing)
 * @returns {typeof FilePicker}
 */
function getFilePicker() {
  return foundry?.applications?.apps?.FilePicker?.implementation ?? FilePicker;
}

class AssetIndexService {
  constructor() {
    this.logger = createLogger('AssetIndexService');
    this.db = null;
    this.isIndexing = false;
    this.lastIndexTime = null;
    this.heartbeatId = null;
    this.initialized = false;
    this._initialIndexPromise = null;
    this._initialIndexResolve = null;
    this._initialIndexComplete = false; // True after first full index completes
    this._fileCount = 0;
    this._folderCount = 0;
  }

  /**
   * Initialize the service - open DB, set up hooks, start heartbeat
   */
  async initialize() {
    if (this.initialized) return;

    this.logger.info('Initializing asset index service...');

    // Create promise for initial readiness
    this._initialIndexPromise = new Promise(resolve => {
      this._initialIndexResolve = resolve;
    });

    // Open IndexedDB
    try {
      this.db = await this._openDB();
      this.logger.info('IndexedDB opened successfully');
    } catch (err) {
      this.logger.error('Failed to open IndexedDB, falling back to memory-only mode', err);
      this.db = null;
    }

    // Check if we have existing cached data
    const hasExistingData = await this._checkExistingIndex();

    if (hasExistingData) {
      // Existing index found - service is immediately ready
      this.logger.info(
        `Using cached index: ${this._fileCount} files, ${this._folderCount} folders`
      );
      this._initialIndexComplete = true;
      this._initialIndexResolve();
    } else {
      this.logger.info('No cached index found, waiting for first index...');
    }

    // Monkey-patch FilePicker methods for immediate sync
    this._patchFilePicker();

    // Start staleness heartbeat - handles both initial and periodic sync
    this._startHeartbeat();

    this.initialized = true;
    this.logger.info('Asset index service initialized');
  }

  /**
   * Check if IndexedDB has a complete index from a previous session
   * @returns {Promise<boolean>}
   */
  async _checkExistingIndex() {
    if (!this.db) return false;

    try {
      const hasEverIndexed = await new Promise((resolve, reject) => {
        const tx = this.db.transaction('meta', 'readonly');
        const request = tx.objectStore('meta').get('hasEverIndexed');
        request.onsuccess = () => resolve(request.result?.value ?? false);
        request.onerror = () => reject(request.error);
      });

      if (!hasEverIndexed) {
        this.logger.debug('No persisted index flag found - first index not started yet');
        return false;
      }

      // Restore last successful completion timestamp when available.
      const storedTime = await new Promise((resolve, reject) => {
        const tx = this.db.transaction('meta', 'readonly');
        const request = tx.objectStore('meta').get('lastIndexTime');
        request.onsuccess = () => resolve(request.result?.value);
        request.onerror = () => reject(request.error);
      });

      if (storedTime) {
        this.lastIndexTime = new Date(storedTime);
      }

      // Count cached records so availability can reflect the existing index state.
      const counts = await new Promise((resolve, reject) => {
        const tx = this.db.transaction(['files', 'folders'], 'readonly');
        let fileCount = 0;
        let folderCount = 0;

        const fileRequest = tx.objectStore('files').count();
        fileRequest.onsuccess = () => {
          fileCount = fileRequest.result;
        };

        const folderRequest = tx.objectStore('folders').count();
        folderRequest.onsuccess = () => {
          folderCount = folderRequest.result;
        };

        tx.oncomplete = () => resolve({ fileCount, folderCount });
        tx.onerror = () => reject(tx.error);
      });

      this._fileCount = counts.fileCount;
      this._folderCount = counts.folderCount;

      return true;
    } catch (err) {
      this.logger.debug(`Failed to check existing index: ${err.message}`);
      return false;
    }
  }

  /**
   * Open IndexedDB database
   * @returns {Promise<IDBDatabase>}
   */
  _openDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = event => {
        const db = event.target.result;

        // Files store - keyed by path
        if (!db.objectStoreNames.contains('files')) {
          const fileStore = db.createObjectStore('files', { keyPath: 'path' });
          fileStore.createIndex('filename', 'filename', { unique: false });
        }

        // Folders store - keyed by path
        if (!db.objectStoreNames.contains('folders')) {
          const folderStore = db.createObjectStore('folders', { keyPath: 'path' });
          folderStore.createIndex('name', 'name', { unique: false });
        }

        // Metadata store - for tracking index state
        if (!db.objectStoreNames.contains('meta')) {
          db.createObjectStore('meta', { keyPath: 'key' });
        }
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  /**
   * Derive source from path prefix
   * @param {string} path
   * @returns {'data'|'public'}
   */
  _getSourceFromPath(path) {
    const root = path.split('/')[0];
    return PUBLIC_ROOTS.includes(root) ? 'public' : 'data';
  }

  /**
   * Monkey-patch getFilePicker().upload for immediate index updates
   */
  _patchFilePicker() {
    const self = this;

    // Patch upload
    const originalUpload = getFilePicker().upload;
    getFilePicker().upload = async function (source, path, file, options) {
      const result = await originalUpload.call(this, source, path, file, options);

      // Add the uploaded file to index
      if (result?.path && self.db) {
        const filename = result.path.split('/').pop().toLowerCase();
        try {
          const tx = self.db.transaction('files', 'readwrite');
          const store = tx.objectStore('files');
          store.put({ path: result.path, filename });
          self._fileCount++;
          self.logger.debug(`Added uploaded file to index: ${result.path}`);
        } catch (err) {
          self.logger.debug(`Failed to add uploaded file to index: ${err.message}`);
        }
      }

      return result;
    };

    // Patch createDirectory
    const originalCreateDirectory = getFilePicker().createDirectory;
    getFilePicker().createDirectory = async function (source, target, options) {
      const result = await originalCreateDirectory.call(this, source, target, options);

      // Add folder to index
      if (self.db) {
        const name = target.split('/').pop().toLowerCase();
        try {
          const tx = self.db.transaction('folders', 'readwrite');
          const store = tx.objectStore('folders');
          store.put({ path: target, name });
          self._folderCount++;
          self.logger.debug(`Added created folder to index: ${target}`);
        } catch (err) {
          self.logger.debug(`Failed to add folder to index: ${err.message}`);
        }
      }

      return result;
    };

    this.logger.info('FilePicker methods patched for index sync');
  }

  /**
   * Start the staleness heartbeat
   */
  _startHeartbeat() {
    if (this.heartbeatId) {
      clearInterval(this.heartbeatId);
    }

    // Run immediately on start, then every HEARTBEAT_INTERVAL_MS
    this._checkStaleness();

    this.heartbeatId = setInterval(() => {
      this._checkStaleness();
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info(
      `Staleness heartbeat started (every ${HEARTBEAT_INTERVAL_MS / 1000}s, threshold ${STALENESS_THRESHOLD_MS / 1000 / 60}m)`
    );
  }

  /**
   * Check if index is stale and trigger rebuild if needed
   */
  _checkStaleness() {
    // Skip if already indexing
    if (this.isIndexing) return;

    const now = Date.now();
    const isStale =
      !this.lastIndexTime || now - this.lastIndexTime.getTime() > STALENESS_THRESHOLD_MS;

    if (isStale) {
      this.logger.debug('Index is stale, triggering rebuild...');
      this.rebuildIndex();
    }
  }

  /**
   * Stop the heartbeat
   */
  stopSync() {
    if (this.heartbeatId) {
      clearInterval(this.heartbeatId);
      this.heartbeatId = null;
    }
  }

  /**
   * Rebuild the entire index (streaming writes to IndexedDB)
   */
  async rebuildIndex() {
    if (this.isIndexing) {
      this.logger.debug('Index rebuild already in progress, skipping');
      return;
    }

    this.isIndexing = true;
    const startTime = Date.now();
    const isInitialIndex = !this._initialIndexComplete;
    this.logger.info('Starting index rebuild...');

    // Emit start hook for initial index (UI status indicator)
    if (isInitialIndex) {
      emitIndexStatus('start');
    }

    // Clear stores before streaming new data
    if (this.db) {
      try {
        if (isInitialIndex) {
          await new Promise((resolve, reject) => {
            const tx = this.db.transaction('meta', 'readwrite');
            tx.objectStore('meta').put({ key: 'hasEverIndexed', value: true });
            tx.oncomplete = resolve;
            tx.onerror = () => reject(tx.error);
          });
        }
        await this._clearStores();
      } catch (err) {
        this.logger.error('Failed to clear IndexedDB stores', err);
      }
    }

    // Reset counts and progress tracking
    this._fileCount = 0;
    this._folderCount = 0;
    this._lastProgressLog = 0;

    // Define roots to index
    const roots = [
      { source: 'data', path: 'assets' },
      { source: 'data', path: 'modules' },
      { source: 'data', path: 'systems' },
      { source: 'data', path: 'worlds' },
      { source: 'public', path: 'icons' },
      { source: 'public', path: 'sounds' },
    ];

    for (const root of roots) {
      try {
        await this._indexRecursive(root.source, root.path);
      } catch (err) {
        // Root might not exist, that's fine
        this.logger.debug(`Could not index ${root.source}/${root.path}: ${err.message}`);
      }
    }

    this.lastIndexTime = new Date();

    // Store timestamp to IndexedDB (marks index as complete)
    if (this.db) {
      try {
        await this._storeTimestamp(this.lastIndexTime);
      } catch (err) {
        this.logger.error('Failed to store index timestamp', err);
      }
    }

    this.isIndexing = false;

    // Mark initial index as complete and resolve promise
    if (!this._initialIndexComplete) {
      this._initialIndexComplete = true;
      if (this._initialIndexResolve) {
        this._initialIndexResolve();
        this._initialIndexResolve = null;
      }

      // Emit complete hook (UI status indicator)
      emitIndexStatus('complete', {
        fileCount: this._fileCount,
        folderCount: this._folderCount,
      });
    }

    const elapsed = Date.now() - startTime;
    this.logger.info(
      `Index rebuild complete: ${this._fileCount} files, ${this._folderCount} folders indexed in ${elapsed}ms`
    );
  }

  /**
   * Store lastIndexTime in IndexedDB
   */
  async _storeTimestamp(timestamp) {
    await new Promise((resolve, reject) => {
      const tx = this.db.transaction('meta', 'readwrite');
      tx.objectStore('meta').put({ key: 'lastIndexTime', value: timestamp.getTime() });
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
  }

  /**
   * Clear IndexedDB stores and timestamp (marks index as incomplete)
   */
  async _clearStores() {
    await new Promise((resolve, reject) => {
      const tx = this.db.transaction(['files', 'folders', 'meta'], 'readwrite');
      tx.objectStore('files').clear();
      tx.objectStore('folders').clear();
      tx.objectStore('meta').delete('lastIndexTime');
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
  }

  /**
   * Write a batch of files and folders to IndexedDB
   * @param {Array<{path: string, filename: string}>} files
   * @param {Array<{path: string, name: string}>} folders
   */
  async _writeBatch(files, folders) {
    if (!this.db || (files.length === 0 && folders.length === 0)) return;

    await new Promise((resolve, reject) => {
      const tx = this.db.transaction(['files', 'folders'], 'readwrite');
      const fileStore = tx.objectStore('files');
      const folderStore = tx.objectStore('folders');

      for (const file of files) {
        fileStore.put(file);
      }
      for (const folder of folders) {
        folderStore.put(folder);
      }

      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
  }

  /**
   * Recursively index a directory - streams writes per directory
   */
  async _indexRecursive(source, path) {
    try {
      const result = await getFilePicker().browse(source, path);

      // Collect files and folders for this directory
      const files = [];
      const folders = [];

      // Index all files in current directory
      for (const file of result.files) {
        const filename = file.split('/').pop().toLowerCase();
        files.push({ path: file, filename });
      }

      // Collect subdirectories to recurse into
      const dirsToRecurse = [];
      for (const dir of result.dirs) {
        const dirname = dir.split('/').pop();

        // Skip hidden and huge directories
        if (dirname.startsWith('.')) continue;
        if (dirname === 'node_modules') continue;

        // Index the folder itself
        folders.push({ path: dir, name: dirname.toLowerCase() });
        dirsToRecurse.push(dir);
      }

      // Write this directory's contents to IndexedDB immediately
      await this._writeBatch(files, folders);
      this._fileCount += files.length;
      this._folderCount += folders.length;

      // Log progress periodically
      const totalItems = this._fileCount + this._folderCount;
      if (totalItems - this._lastProgressLog >= PROGRESS_LOG_INTERVAL) {
        this.logger.info(
          `Indexing progress: ${this._fileCount} files, ${this._folderCount} folders...`
        );
        this._lastProgressLog = totalItems;

        // Emit progress hook for initial index (UI status indicator)
        if (!this._initialIndexComplete) {
          emitIndexStatus('progress', {
            fileCount: this._fileCount,
            folderCount: this._folderCount,
          });
        }
      }

      // Recurse into subdirectories (after writing, so memory is freed)
      for (const dir of dirsToRecurse) {
        await this._indexRecursive(source, dir);
      }
    } catch {
      // Access denied or path invalid - skip silently
    }
  }

  /**
   * Search the index for matching files
   * @param {string} query - Search query (filename or path segment)
   * @param {string} type - File type filter (image, audio, video, text, font, any)
   * @param {string} sourceFilter - Source filter (all, user, core)
   * @returns {Promise<string[]>} Array of matching file paths
   */
  async search(query, type = 'any', sourceFilter = 'all') {
    // Wait for initial index if not yet complete
    if (this._initialIndexPromise) {
      await this._initialIndexPromise;
    }

    if (!this.db) {
      return [];
    }

    const lowerQuery = query.toLowerCase();
    const results = [];

    const extensions = {
      image: ['.png', '.jpg', '.jpeg', '.webp', '.gif', '.svg'],
      audio: ['.mp3', '.ogg', '.wav', '.flac', '.m4a'],
      video: ['.mp4', '.webm', '.mkv'],
      text: ['.txt', '.md', '.json', '.js', '.css'],
      font: ['.ttf', '.otf', '.woff', '.woff2'],
    };

    return new Promise(resolve => {
      const tx = this.db.transaction('files', 'readonly');
      const store = tx.objectStore('files');
      const request = store.openCursor();

      request.onsuccess = event => {
        const cursor = event.target.result;

        if (!cursor) {
          resolve(results);
          return;
        }

        const { path, filename } = cursor.value;

        // Check source filter
        const source = this._getSourceFromPath(path);
        if (sourceFilter === 'user' && source !== 'data') {
          cursor.continue();
          return;
        }
        if (sourceFilter === 'core' && source !== 'public') {
          cursor.continue();
          return;
        }

        // Check query match
        if (!filename.includes(lowerQuery) && !path.toLowerCase().includes(lowerQuery)) {
          cursor.continue();
          return;
        }

        // Check type filter
        if (type !== 'any') {
          const exts = extensions[type];
          if (exts && !exts.some(ext => filename.endsWith(ext))) {
            cursor.continue();
            return;
          }
        }

        results.push(path);
        cursor.continue();
      };

      request.onerror = () => {
        this.logger.error('IndexedDB cursor error during search');
        resolve(results);
      };
    });
  }

  /**
   * Search the index for matching folders
   * @param {string} query - Search query (folder name or path segment)
   * @param {string} sourceFilter - Source filter (all, user, core)
   * @returns {Promise<string[]>} Array of matching folder paths
   */
  async searchFolders(query, sourceFilter = 'all') {
    // Wait for initial index if not yet complete
    if (this._initialIndexPromise) {
      await this._initialIndexPromise;
    }

    if (!this.db) {
      return [];
    }

    const lowerQuery = query.toLowerCase();
    const results = [];

    return new Promise(resolve => {
      const tx = this.db.transaction('folders', 'readonly');
      const store = tx.objectStore('folders');
      const request = store.openCursor();

      request.onsuccess = event => {
        const cursor = event.target.result;

        if (!cursor) {
          resolve(results);
          return;
        }

        const { path, name } = cursor.value;

        // Check source filter
        const source = this._getSourceFromPath(path);
        if (sourceFilter === 'user' && source !== 'data') {
          cursor.continue();
          return;
        }
        if (sourceFilter === 'core' && source !== 'public') {
          cursor.continue();
          return;
        }

        // Check query match
        if (!name.includes(lowerQuery) && !path.toLowerCase().includes(lowerQuery)) {
          cursor.continue();
          return;
        }

        results.push(path);
        cursor.continue();
      };

      request.onerror = () => {
        this.logger.error('IndexedDB cursor error during folder search');
        resolve(results);
      };
    });
  }

  /**
   * Browse a folder - list immediate contents (files and subfolders)
   * @param {string} path - Folder path to browse
   * @param {string} source - Source (data or public)
   * @returns {Promise<{files: string[], folders: string[]}>}
   */
  async browseFolder(path, source = 'data') {
    // Wait for initial index if not yet complete
    if (this._initialIndexPromise) {
      await this._initialIndexPromise;
    }

    try {
      const result = await getFilePicker().browse(source, path);
      return {
        files: result.files || [],
        folders: result.dirs || [],
      };
    } catch (err) {
      throw new Error(`Cannot browse folder "${path}": ${err.message}`);
    }
  }

  /**
   * Get index stats
   */
  getStats() {
    return {
      fileCount: this._fileCount,
      folderCount: this._folderCount,
      lastIndexTime: this.lastIndexTime,
      isIndexing: this.isIndexing,
    };
  }

  /**
   * Check if the index is ready for searching
   * @returns {boolean}
   */
  isReady() {
    return this.db !== null && this._initialIndexComplete;
  }

  /**
   * Get availability status for dynamic tool descriptions
   * @returns {{available: boolean, reason?: string}}
   */
  getAvailability() {
    if (!this.db) {
      return { available: false, reason: 'IndexedDB not available' };
    }
    if (!this._initialIndexComplete) {
      return { available: false, reason: 'Initial indexing in progress' };
    }
    if (!this.isIndexing && this._fileCount === 0 && this._folderCount === 0) {
      return { available: false, reason: 'No files indexed' };
    }
    return { available: true };
  }
}

// Singleton instance
export const assetIndexService = new AssetIndexService();

/* eslint-disable max-depth */
import { createLogger, isDebugEnabled } from '../utils/logger.js';
import {
  formatToolCallDisplay,
  getToolDisplayContent,
  getToolContentSummary,
} from '../utils/message-utils.js';
import { MarkdownRenderer } from '../lib/markdown-renderer.js';
import { retrieveToolJustification } from './tool-loop-handler.js';
/**
 * ChatHandler - Single source of truth for all chat conversation flow
 * Orchestrates between AI, tools, conversation state, and UI
 */

class ChatHandler {
  constructor(conversationManager) {
    this.conversationManager = conversationManager;
    this.logger = createLogger('ChatHandler');
  }

  /**
   * Main entry point for processing user messages
   * Handles the complete flow: user input -> AI -> tools -> UI
   */
  async processUserMessage(message, user, options = {}) {
    try {
      // Add user message to conversation state
      this.addMessageToConversation('user', message);

      // Notify UI if callback provided
      if (options.onUserMessage) {
        options.onUserMessage({ role: 'user', content: message, user });
      }

      // Delegate orchestration to ConversationEngine
      const { ConversationEngine } = await import('./conversation-engine.js');
      const engine = new ConversationEngine(this.conversationManager);

      const finalResponse = await engine.processTurn({
        signal: options.signal,
        onAssistantMessage: async msg => {
          // Support ephemeral messages (display only) by checking for either content or display
          if (msg?.role === 'assistant' && (msg?.content || msg?.display)) {
            // Only add to conversation if this is NOT a tool-call response.
            // Messages with tool calls are already added by tool-loop-handler before execution.
            // Adding here would cause duplicate log entries.
            if (msg.content && !msg.toolCalls && !msg._fromToolLoop) {
              this.addMessageToConversation('assistant', msg.content);
            }
            await this.addMessageToUI(
              { role: 'assistant', content: msg.content, display: msg.display || msg.content },
              options
            );
          }
        },
        onToolResult: async toolResult => await this.handleToolResult(toolResult, options),
      });

      return finalResponse;
    } catch (error) {
      // Handle cancellation — not an error, just user-initiated stop
      if (error.name === 'AbortError' || error.message === 'Process was cancelled') {
        this.logger.info('Process cancelled by user');
        const cancelMessage = {
          role: 'assistant',
          content: 'Process cancelled by user',
          display: '🛑 Process cancelled',
          noGroup: true,
        };
        this.addMessageToUI(cancelMessage, options);
        return cancelMessage;
      }

      this.logger.error('Error processing user message', error);

      // Invoke onError callback to restore user's message to input field
      // This is for ACTUAL errors (not cancellation) where we want to allow retry
      if (options.onError) {
        options.onError({ originalMessage: message, error });
      }

      // Check for 503 Service Unavailable or other API connection issues
      let friendlyMessage = `Error: ${error.message}`;
      let displayMessage = `${error.message}`;

      if (error.message.includes('503') || error.message.includes('Service Unavailable')) {
        friendlyMessage =
          'The AI service is currently unavailable (503). This is typically a temporary issue with the AI provider. Please try again in a few moments.';
        displayMessage = `⚠️ **AI Service Unavailable**\n\nThe AI endpoint is experiencing issues (503). This is usually temporary.\n\n*Error details: ${error.message}*`;
      } else if (
        error.message.includes('Failed to fetch') ||
        error.message.includes('NetworkError')
      ) {
        friendlyMessage =
          'Network connection failed. Please check your internet connection and API settings.';
        displayMessage = `**Network Error**\n\nFailed to connect to the AI service.\n\n*Error details: ${error.message}*`;
      }

      // API/Network errors: Show via FoundryVTT notification system
      if (globalThis.ui?.notifications?.error) {
        ui.notifications.error(`Simulacrum: ${error.message}`, { permanent: false });
      } else {
        this.logger.error(`Simulacrum Error: ${error.message}`);
      }

      // CRITICAL: fallback response for the chat UI
      const errorMessage = {
        role: 'assistant',
        content: friendlyMessage,
        display: displayMessage,
        error,
      };

      // Ensure the error is displayed in the chat interface
      this.addMessageToUI(errorMessage, options);

      return errorMessage;
    }
  }

  /**
   * Handle AI response - add to conversation and execute tools if needed
   */
  async handleAIResponse(aiResponse, options = {}) {
    // Skip adding parse errors to conversation/UI (they're for AI correction only)
    if (aiResponse._parseError) {
      return await this.handleParseError(aiResponse, options);
    }

    // Add assistant response to conversation
    this.addMessageToConversation(
      'assistant',
      aiResponse.content,
      aiResponse.toolCalls,
      null,
      aiResponse.provider_metadata
    );

    // Add to UI
    await this.addMessageToUI(
      {
        role: 'assistant',
        content: aiResponse.content,
        display: aiResponse.display || aiResponse.content,
      },
      options
    );

    // Execute tools if present; pass full response so parseError is preserved
    if (aiResponse.toolCalls && aiResponse.toolCalls.length > 0) {
      return await this.handleToolExecution(aiResponse, options);
    }

    // No tools - check if we should continue autonomous loop
    return await this.handleAutonomousFlow(aiResponse, options);
  }

  /**
   * Handle parse errors by continuing AI flow for correction
   */
  async handleParseError(parseErrorResponse, options = {}) {
    if (isDebugEnabled()) {
      const { createLogger } = await import('../utils/logger.js');
      const logger = createLogger('ChatHandler');
      logger.warn('ChatHandler handling parse error:', {
        parseErrorType: parseErrorResponse._parseError,
        content: parseErrorResponse.content || '(empty)',
        hasToolCalls: !!(parseErrorResponse.toolCalls && parseErrorResponse.toolCalls.length > 0),
        retryCount: options._retryCount || 0,
      });
    }
    // Append assistant failed turn + system correction to conversation
    const { appendEmptyContentCorrection } = await import('./correction.js');
    appendEmptyContentCorrection(this.conversationManager, parseErrorResponse);

    // Continue the autonomous flow to get corrected response
    return await this.handleAutonomousFlow(parseErrorResponse, options);
  }

  /**
   * Execute tools and continue conversation flow
   * Decomposed to reduce complexity
   */
  async handleToolExecution(aiResponse, options = {}) {
    try {
      const finalResponse = await this._executeToolLoop(aiResponse, options);
      return await this._processToolLoopOutcome(finalResponse, options);
    } catch (error) {
      this.logger.error('Error executing tools', error);

      const errorMessage = {
        role: 'assistant',
        content: `Tool execution error: ${error.message}`,
        display: `${error.message}`,
      };
      this.addMessageToConversation('assistant', errorMessage.content);
      this.addMessageToUI(errorMessage, options);
      return errorMessage;
    }
  }

  async _executeToolLoop(aiResponse, options) {
    const { processToolCallLoop } = await import('./tool-loop-handler.js');
    const { SimulacrumCore } = await import('./simulacrum-core.js');
    const { toolRegistry } = await import('./tool-registry.js');

    const tools = toolRegistry.getToolSchemas();
    const legacyMode = game?.settings?.get('simulacrum', 'legacyMode') ?? false;
    const currentToolSupport = !legacyMode;

    // Execute tools and get final response
    return await processToolCallLoop({
      initialResponse: aiResponse,
      tools,
      conversationManager: this.conversationManager,
      aiClient: SimulacrumCore.aiClient,
      getSystemPrompt: SimulacrumCore.getSystemPrompt.bind(SimulacrumCore),
      currentToolSupport,
      signal: options.signal,
      onToolResult: toolResult => this.handleToolResult(toolResult, options),
      onToolPending: options.onToolPending,
    });
  }

  async _processToolLoopOutcome(finalResponse, options) {
    // Handle tool limit reached error
    if (finalResponse._toolLimitReachedError) {
      this.conversationManager.updateSystemMessage(finalResponse.content);
      const aiSummaryResponse = await this.handleAutonomousFlow(finalResponse, options);
      // Add the AI's summary to conversation and UI
      this.addMessageToConversation('assistant', aiSummaryResponse.content);
      this.addMessageToUI(
        {
          role: 'assistant',
          content: aiSummaryResponse.content,
          display: aiSummaryResponse.display || aiSummaryResponse.content,
        },
        options
      );
      return aiSummaryResponse;
    }

    // Add final response if different from last message
    if (finalResponse && finalResponse.content) {
      const lastMessage =
        this.conversationManager.messages[this.conversationManager.messages.length - 1];
      if (lastMessage?.role !== 'assistant' || lastMessage?.content !== finalResponse.content) {
        this.addMessageToConversation(
          'assistant',
          finalResponse.content,
          null,
          null,
          finalResponse.provider_metadata
        );
        this.addMessageToUI(
          {
            role: 'assistant',
            content: finalResponse.content,
            display: finalResponse.display || finalResponse.content,
          },
          options
        );
      }
    }
    return finalResponse;
  }

  /**
   * Handle autonomous flow continuation (when no tools but should continue)
   */
  async handleAutonomousFlow(response, options = {}) {
    // Check for parse errors that need retry
    if (response._parseError) {
      return await this.retryAIResponse(options);
    }

    // For other autonomous cases, just return the response
    // This is where we would check for end_task or continue the conversation
    return response;
  }

  /**
   * Retry AI response generation for parse errors
   */
  async retryAIResponse(options = {}) {
    const maxRetries = 3;
    const currentRetries = (options._retryCount || 0) + 1;

    if (currentRetries > maxRetries) {
      await this._logRetryExhausted(currentRetries, maxRetries);
      const errorMessage = {
        role: 'assistant',
        content:
          'Unable to generate a proper response after multiple attempts. Please try rephrasing your request.',
        display: 'Unable to generate a proper response after multiple attempts.',
      };
      this.addMessageToUI(errorMessage, options);
      return errorMessage;
    }

    try {
      const { SimulacrumCore } = await import('./simulacrum-core.js');
      await this._logRetryAttempt(currentRetries);

      // Get corrected AI response
      const aiResponse = await SimulacrumCore.generateResponse(
        this.conversationManager.getMessages(),
        { signal: options.signal }
      );

      // Recursively handle the new response with retry tracking
      return await this.handleAIResponse(aiResponse, {
        ...options,
        _retryCount: currentRetries,
      });
    } catch (error) {
      this.logger.error('Error during AI response retry', error);

      const errorMessage = {
        role: 'assistant',
        content: `Retry failed: ${error.message}`,
        display: `Retry failed: ${error.message}`,
      };
      this.addMessageToConversation('assistant', errorMessage.content);
      this.addMessageToUI(errorMessage, options);
      return errorMessage;
    }
  }

  async _logRetryExhausted(currentRetries, maxRetries) {
    try {
      const { isDebugEnabled, createLogger } = await import('../utils/logger.js');
      if (isDebugEnabled()) {
        const conversationMessages = this.conversationManager.getMessages();
        createLogger('AIDiagnostics').error('assistant.empty_response.exhausted', {
          maxRetries,
          retryCount: currentRetries,
          conversationLength: conversationMessages.length,
          recentMessages: conversationMessages.slice(-5).map(msg => ({
            role: msg.role,
            hasToolCalls: !!(msg.tool_calls && msg.tool_calls.length > 0),
          })),
        });
      }
    } catch {
      /* intentionally empty */
    }
  }

  async _logRetryAttempt(currentRetries) {
    try {
      const { isDebugEnabled, createLogger } = await import('../utils/logger.js');
      if (isDebugEnabled()) {
        const last =
          this.conversationManager.messages[this.conversationManager.messages.length - 1];
        createLogger('AIDiagnostics').info('assistant.empty_response.retry', {
          attempt: currentRetries,
          lastRole: last?.role,
          hasToolCalls: Array.isArray(last?.tool_calls) && last?.tool_calls.length > 0,
        });
      }
    } catch {
      /* intentionally empty */
    }
  }

  /**
   * Handle individual tool results during execution
   * Task-09: Enhanced to format tool results with status icons
   */
  async handleToolResult(toolResult, options = {}) {
    // Add tool result to conversation
    if (toolResult.role === 'tool') {
      // FIX: Do not add to conversation here, as tool-loop-handler already adds it internally.
      // this.addMessageToConversation('tool', toolResult.content, null, toolResult.toolCallId);

      // Check for silent/hidden tools - skip UI rendering
      const hiddenTools = ['end_loop'];
      // Tools that don't need justification displayed (self-explanatory from context)
      const noJustificationTools = ['read_tool_output'];
      // Tools that render their display directly without tool card wrapper
      const directDisplayTools = ['manage_task'];
      let isSilent = hiddenTools.includes(toolResult.toolName);
      if (!isSilent) {
        try {
          const parsed =
            typeof toolResult.content === 'string'
              ? JSON.parse(toolResult.content)
              : toolResult.content;
          isSilent = parsed?._silent === true;
        } catch (_e) {
          /* not JSON, not silent */
        }
      }

      // Task-09: Format tool result with rich HTML display if it has a toolName (and is not silent)
      if (toolResult.toolName && options.onAssistantMessage && !isSilent) {
        // Direct display tools: render their display property directly without tool card wrapper
        if (directDisplayTools.includes(toolResult.toolName)) {
          const payload = {
            toolCallId: toolResult.toolCallId,
            toolName: toolResult.toolName,
          };

          // Prefer direct callback for removal
          if (options.onToolRemove) {
            options.onToolRemove(payload);
          }

          // Emit hook (standard event for pending removal? or result?)
          // Maintained for backward compatibility, but arguably this should be simulacrumToolRemove?
          // Existing listeners likely expect 'simulacrumToolResult' to imply completion.
          Hooks.callAll('simulacrumToolResult', payload);

          const rawDisplay = getToolDisplayContent(toolResult);
          // Only show if there's actual display content (skip empty displays like start_task)
          if (rawDisplay && rawDisplay.trim()) {
            // Check if display is already HTML (starts with <) or needs markdown rendering
            let formattedDisplay = rawDisplay;
            if (!rawDisplay.trim().startsWith('<')) {
              formattedDisplay = await MarkdownRenderer.render(rawDisplay, { force: true });
            }
            // Extract proper content summary (not raw JSON)
            const contentSummary = getToolContentSummary(toolResult) || '';
            await this.addMessageToUI(
              {
                role: 'assistant',
                content: contentSummary,
                display: formattedDisplay,
                _fromToolLoop: true, // Prevent duplicate conversation entry
              },
              options
            );
          }
          return; // Skip standard tool card formatting
        }

        // Retrieve justification stored during pending phase (skip for self-explanatory tools)
        const justification = noJustificationTools.includes(toolResult.toolName)
          ? ''
          : retrieveToolJustification(toolResult.toolCallId);

        let preRendered = null;
        try {
          // Task-Fix: Unwrap content if it's JSON to prevent leaking raw JSON string.
          // Prioritize 'display' property using shared utility.
          // CRITICAL: Always render valid Markdown, even if 'display' property is used, as tools return Markdown.
          // Use force: true to ensure mixed HTML/Markdown (like @UUID which might look like tags?) is processed.
          const rawDisplay = getToolDisplayContent(toolResult);
          if (rawDisplay) {
            preRendered = await MarkdownRenderer.render(rawDisplay, { force: true });
          } else {
            // Fallback: Check if content is JSON. If so, SKIP rendering and let formatToolCallDisplay handle it
            // (it has smarter logic for extracting display/message/error from JSON).
            // If NOT JSON (e.g. legacy string output), render it as markdown.
            const content = toolResult.content;
            let isJson = false;
            if (typeof content === 'string' && content.trim().startsWith('{')) {
              try {
                JSON.parse(content);
                isJson = true;
              } catch (e) {}
            }

            if (!isJson) {
              preRendered = await MarkdownRenderer.render(content);
            }
          }
        } catch (e) {
          this.logger.warn('Failed to pre-render tool content', e);
        }

        const formattedDisplay = formatToolCallDisplay(
          toolResult,
          toolResult.toolName,
          preRendered,
          justification
        );

        const payload = {
          toolCallId: toolResult.toolCallId,
          toolName: toolResult.toolName,
          formattedDisplay,
          content: toolResult.content,
        };

        // Prefer direct callback if provided (Closed Loop for Active UI)
        if (options.onToolResult) {
          await options.onToolResult(payload);
        }

        // Emit hook for global observability (Background tasks / Macros / Other Users)
        Hooks.callAll('simulacrumToolResult', payload);
      }
    } else if (toolResult.role === 'assistant') {
      // Allow empty content to serve as anchor bubbles for tool cards (Fix for Floating Tool Card bug)
      // Only add assistant messages that have actual content (and aren't from loop) to conversation history
      if (!toolResult._fromToolLoop && toolResult.content) {
        this.addMessageToConversation('assistant', toolResult.content);
      }
      await this.addMessageToUI(
        {
          role: 'assistant',
          content: toolResult.content,
          display: toolResult.display || toolResult.content,
        },
        options
      );
    }
  }

  /**
   * Add message to conversation state only
   */
  addMessageToConversation(role, content, toolCalls = null, toolCallId = null, metadata = null) {
    this.conversationManager.addMessage(role, content, toolCalls, toolCallId, metadata);
  }

  /**
   * Add message to UI only (through callback)
   */
  /**
   * Add message to UI only (through callback)
   */
  async addMessageToUI(message, options = {}) {
    if (options.onAssistantMessage && message.role === 'assistant') {
      try {
        await options.onAssistantMessage(message);
      } catch (error) {
        this.logger.error('Error in UI callback', error);
      }
    }
  }

  /**
   * Clear conversation history and interaction log
   */
  async clearConversation() {
    this.conversationManager.clear();
    await this.conversationManager.save();
    // Clear the interaction log when conversation is cleared
    const { interactionLogger } = await import('./interaction-logger.js');
    await interactionLogger.clear();
  }
}

