/**
 * Document Creation Tool
 */
export class DocumentCreateTool extends BaseTool {
  constructor() {
    super(
      'create_document',
      "Create a new document in the world or a compendium pack. The `data` parameter must contain the document's fields (e.g., `name`, `type`, and any system-specific fields nested under `system`). Use `inspect_document_schema` to discover required fields and valid structure for a given document type. Use `list_document_schemas` to discover available document types and subtypes. Pass `documentType` as \"Compendium\" to create a new world compendium pack (requires `data.name`, `data.label`, and `data.type`)."
    );
    this.requiresConfirmation = true;
    this.schema = {
      type: 'object',
      properties: {
        documentType: {
          type: 'string',
          description:
            'The document class to create (e.g., Actor, Item, JournalEntry, RollTable, Scene). Use `list_document_schemas` to discover available types.',
        },
        data: {
          type: 'object',
          description:
            'The document\'s field data as a JSON object. Must include at least `name` and, for typed documents, a `type` field (e.g., "npc", "weapon"). Structure varies by document type — use `inspect_document_schema` to discover valid fields. Embedded documents go in their respective arrays (e.g., `pages` for JournalEntry, `items` for Actor).',
        },
        folder: {
          type: 'string',
          description:
            'The ID of an existing Folder to place the document in. Omit to create at root level.',
        },
        pack: {
          type: 'string',
          description:
            'The compendium pack ID to create the document in (e.g., "dnd5e.items"). The pack must be unlocked and match the document type. Omit to create in the world.',
        },
      },
      required: ['documentType', 'data'],
    };
  }

  /**
   * Get the parameter schema for this tool
   */
  getParameterSchema() {
    return this._addResponseParam(this.schema);
  }

  /**
   * Get confirmation details for this tool
   */
  async getConfirmationDetails(params) {
    const { documentType, data } = params;

    // Mock DocumentAPI call (would be real in actual implementation)
    const mockSchema = { fields: ['name', 'type'], systemFields: ['attributes'] };

    return {
      type: 'create',
      title: `Create ${documentType} Document`,
      details: `Creating ${documentType}: ${data.name || 'Unnamed'}`,
      availableFields: mockSchema.fields,
      systemFields: mockSchema.systemFields,
    };
  }

  /**
   * Create a new world compendium pack
   * @param {Object} params - Tool parameters with data.name, data.label, data.type
   * @returns {Promise<Object>} Creation result
   */
  async _createCompendium(params) {
    const { data } = params;

    if (!game.user?.isGM) {
      return {
        content: 'Only GMs can create compendium packs',
        display: 'Permission denied: GM required',
        error: { message: 'Only GMs can create compendium packs', type: 'PERMISSION_DENIED' },
      };
    }

    if (!data?.name || !data?.label || !data?.type) {
      return {
        content:
          'Creating a Compendium requires `data.name` (lowercase pack name with hyphens), `data.label` (display name), and `data.type` (document type the pack stores, e.g. Actor, Item, JournalEntry).',
        display: 'Missing required fields for compendium creation',
        error: { message: 'Missing name, label, or type', type: 'VALIDATION_ERROR' },
      };
    }

    const fullPackId = data.name.includes('.') ? data.name : `world.${data.name}`;
    if (game.packs.has(fullPackId)) {
      return {
        content: `Compendium pack "${fullPackId}" already exists`,
        display: `Pack already exists: ${fullPackId}`,
        error: { message: `Pack "${fullPackId}" already exists`, type: 'CONFLICT' },
      };
    }

    try {
      const packName = data.name.includes('.') ? data.name.split('.')[1] : data.name;
      const newPack = await CompendiumCollection.createCompendium({
        name: packName,
        label: data.label,
        type: data.type,
        packageType: 'world',
      });

      const packId = newPack.metadata.id;
      const msg = `Created compendium pack "${newPack.metadata.label}" (${packId}) for ${data.type} documents`;
      return {
        content: JSON.stringify({ message: msg, packId, metadata: newPack.metadata }, null, 2),
        display: `Created compendium **${newPack.metadata.label}** (${packId})`,
      };
    } catch (error) {
      return {
        content: `Failed to create compendium: ${error.message}`,
        display: `Compendium creation failed: ${error.message}`,
        error: { message: error.message, type: 'CREATE_FAILED' },
      };
    }
  }

  async _promoteSystemFields(documentType, data) {
    try {
      const { DocumentAPI } = await import('../core/document-api.js');
      const schema = DocumentAPI.getDocumentSchema(documentType);

      if (!schema?.systemFields || !Array.isArray(schema.systemFields)) return;

      if (!data.system) data.system = {};

      for (const field of schema.systemFields) {
        this._migrateField(data, field, schema);
      }
    } catch (migrationError) {
      // Ignoring migration errors
    }
  }

  _migrateField(data, field, schema) {
    // Skip if field not at root or already in system
    if (data[field] === undefined || data.system[field] !== undefined) return;

    const targetType = schema.systemFieldDetails?.[field]?.type;
    const value = data[field];

    if (typeof value === 'string' && (targetType === 'schema_field' || targetType === 'object')) {
      data.system[field] = { value: value };
    } else {
      data.system[field] = value;
    }

    delete data[field];
  }

  /**
   * Execute document creation
   * @param {Object} parameters - Creation parameters
   * @returns {Promise<Object>} Creation result
   */
  async execute(parameters) {
    try {
      const { documentType, data } = parameters;

      // Compendium creation branch — early return before normal document flow
      if (documentType === 'Compendium') {
        return this._createCompendium(parameters);
      }

      // Check if document type is valid
      if (!this.isValidDocumentType(documentType)) {
        return {
          content: `Document type "${documentType}" not available in current system`,
          display: `Unknown document type: ${documentType}`,
          error: {
            message: `Document type "${documentType}" not available in current system`,
            type: 'UNKNOWN_DOCUMENT_TYPE',
          },
        };
      }

      // Validate parameters
      this.validateParameters(parameters, this.schema);

      // Validate unknown fields - catch fields that would be silently ignored
      const { SchemaValidator } = await import('../utils/schema-validator.js');
      const unknownFieldsResult = SchemaValidator.validateUnknownFields(documentType, data);
      if (!unknownFieldsResult.valid && unknownFieldsResult.unknownFields.length > 0) {
        // Build the full schema response including embedded document schemas
        const { DocumentAPI } = await import('../core/document-api.js');
        const schemaResponse = await this.#buildSchemaResponse(
          documentType,
          unknownFieldsResult,
          DocumentAPI
        );

        return {
          content: schemaResponse.message,
          display: `Unknown fields: ${unknownFieldsResult.unknownFields.join(', ')}`,
          error: {
            message: schemaResponse.message,
            type: 'UNKNOWN_FIELDS',
            unknownFields: unknownFieldsResult.unknownFields,
            schema: schemaResponse.schema,
          },
        };
      }

      // Generic Schema Migration (String -> Object promotion)
      await this._promoteSystemFields(documentType, data);

      // Validate image URLs — invalid ones are blanked, not rejected
      const imageWarnings = await this.validateImageUrls(data);

      // Correct malformed UUIDs using schema-derived reference fields
      const uuidWarnings = this.validateUuids(documentType, data, parameters.pack);

      // Mock DocumentAPI for testing - in real implementation, this would use this.documentAPI
      const { DocumentAPI } = await import('../core/document-api.js');

      // RESHAPE DATA: Transform AI-friendly arrays into Foundry-required objects (e.g., MappingField)
      const documentClass = CONFIG[documentType]?.documentClass;
      if (documentClass) {
        this.#reshapeData(data, documentClass, data.type);
      }

      let document;
      if (parameters.pack) {
        const packCollection = game.packs.get(parameters.pack);
        if (!packCollection) {
          return {
            content: `Compendium pack "${parameters.pack}" not found`,
            display: `Pack not found: ${parameters.pack}`,
            error: { message: `pack "${parameters.pack}" not found`, type: 'PACK_NOT_FOUND' },
          };
        }

        // Check if pack is locked
        if (packCollection.locked) {
          return {
            content: `Compendium pack "${parameters.pack}" is locked. Cannot create document.`,
            display: `Pack is locked: ${parameters.pack}`,
            error: { message: `pack "${parameters.pack}" is locked`, type: 'PACK_LOCKED' },
          };
        }

        // Validate document type against pack type
        if (packCollection.documentName !== documentType) {
          return {
            content: `Pack "${parameters.pack}" contains ${packCollection.documentName} documents, but you requested ${documentType}`,
            display: `Type mismatch: Pack contains ${packCollection.documentName}`,
            error: { message: `Type mismatch`, type: 'TYPE_MISMATCH' },
          };
        }

        // Create directly in pack - wrap in try/catch to capture validation errors
        // that Foundry might throw during creation
        try {
          document = await documentClass.create(data, { pack: parameters.pack });
        } catch (packCreateError) {
          // Re-throw to be handled by the outer catch block with ValidationErrorHandler
          throw packCreateError;
        }
      } else {
        document = await DocumentAPI.createDocument(documentType, data);
      }

      if (!document) {
        // Foundry sometimes returns null/undefined on validation failure instead of throwing
        // This can happen when strict validation fails during document instantiation
        // Try to provide more context by attempting a validation
        try {
          const testDoc = new documentClass(data);
          testDoc.validate({ strict: true, fields: true, joint: true });
        } catch (validationError) {
          // Found the actual error - rethrow to be handled by ValidationErrorHandler
          throw validationError;
        }
        // If validation passes but still got null, return generic error
        return {
          content: `Document creation failed. The document could not be created. Check that all required fields are provided and all values are valid for the ${documentType} document type.`,
          display: `Failed to create ${documentType} document`,
          error: {
            message: 'Document creation failed - no document returned',
            type: 'CREATE_FAILED',
            hint: 'Check browser console for additional Foundry validation errors',
          },
        };
      }

      // Fetch the full document with embedded data for verification
      // IMPORTANT: Pass pack parameter so we look in the right place!
      const verificationOpts = { includeEmbedded: true };
      if (parameters.pack) verificationOpts.pack = parameters.pack;

      const fullDocument = await DocumentAPI.getDocument(
        documentType,
        document.id || document._id,
        verificationOpts
      );

      // Register the read so the AI can immediately edit it if needed
      if (fullDocument) {
        documentReadRegistry.registerRead(
          documentType,
          fullDocument.id || fullDocument._id,
          fullDocument
        );
      }

      const message = `Created @UUID[${documentType}.${fullDocument._id || fullDocument.id}]{${fullDocument.name || fullDocument._id}}`;
      const contentPayload = {
        message,
        document: fullDocument,
      };
      const allWarnings = [...imageWarnings, ...uuidWarnings];
      if (allWarnings.length > 0) {
        contentPayload.warnings = allWarnings;
      }

      return {
        content: JSON.stringify(contentPayload, null, 2),
        display: `Created **${fullDocument.name || fullDocument._id || fullDocument.id}** (${documentType})`,
        document: fullDocument,
      };
    } catch (error) {
      // Attempt to auto-correct invalid document ID fields and retry once
      try {
        const retryResult = await this.#retryWithCorrectedIds(error, parameters);
        if (retryResult) return retryResult;
      } catch {
        // Retry also failed — fall through to original error response
      }
      return ValidationErrorHandler.createToolErrorResponse(
        error,
        'create',
        parameters.documentType
      );
    }
  }

  /**
   * Reshape data to match Foundry's strict DataModel expectations.
   * Specifically transforms Arrays -> ID-keyed Objects for MappingFields.
   * @param {Object} data - The data object to reshape (modified in place)
   * @param {Class} documentClass - The DataModel class
   * @param {String} [documentSubType] - The sub-type (e.g., 'weapon') for system data lookup
   */
  #reshapeData(data, documentClass, documentSubType) {
    if (!data || typeof data !== 'object') return;

    // 1. Get the relevant schema
    // If we are looking at 'system' data, we need the type-specific model
    const schema = documentClass.schema;

    // Attempt to handle system data reshaping
    if (data.system && typeof data.system === 'object') {
      try {
        const systemModel = CONFIG[documentClass.documentName]?.dataModels?.[documentSubType];
        if (systemModel && systemModel.schema) {
          this.#reshapeDataFields(data.system, systemModel.schema);
        } else if (documentClass.schema?.fields?.system?.model?.schema) {
          // Some systems handle it differently, simplified fallback
          this.#reshapeDataFields(data.system, documentClass.schema.fields.system.model.schema);
        }
      } catch (e) {
        // Ignore system lookup errors
      }
    }

    // 2. Reshape top-level fields
    // (Note: Top level fields on Documents are rarely MappingFields, but good for completeness)
    if (schema) {
      this.#reshapeDataFields(data, schema);
    }
  }

  /**
   * Recursive field processor for #reshapeData
   * @param {Object} dataObject - The object containing data properties
   * @param {Schema} schema - The schema defining those properties
   */
  #reshapeDataFields(dataObject, schema) {
    if (!schema?.fields) return;

    for (const [fieldName, value] of Object.entries(dataObject)) {
      if (!value) continue;
      const field = schema.fields[fieldName];
      if (!field) continue;

      // CHECK: Array provided for a MappingField?
      // MappingFields (like system.activities in dnd5e) require ID-keyed objects
      if (Array.isArray(value)) {
        // USE HELPER: Check full prototype chain for MappingField ancestry
        // (Fixes issue where 'ActivitiesField' subclass was not detected)
        if (this.#isMappingField(field)) {
          // TRANSFORM: Array -> Object with random IDs
          const obj = {};
          value.forEach(item => {
            // Use standard randomID if available, else simple fallback
            const id =
              typeof foundry !== 'undefined'
                ? foundry.utils.randomID()
                : Math.random().toString(36).substring(2, 18);
            obj[id] = item;

            // Recurse into the item if it has its own schema (e.g. Activity DataModel)
            if (field.model?.schema) {
              this.#reshapeDataFields(item, field.model.schema);
            }
          });
          dataObject[fieldName] = obj;
          continue; // Done with this field
        }
      }

      // Recurse for nested objects (SchemaField)
      if (
        field.constructor.name === 'SchemaField' &&
        typeof value === 'object' &&
        !Array.isArray(value)
      ) {
        this.#reshapeDataFields(value, field); // SchemaField acts as schema
      }
    }
  }

  /**
   * Helper to identify MappingField instances by checking prototype chain.
   * Handles subclasses like ActivitiesField.
   * @param {DataField} field
   * @returns {boolean}
   */
  #isMappingField(field) {
    if (!field) return false;

    // Check direct constructor
    if (field.constructor.name === 'MappingField') return true;

    // Walk prototype chain to check for inheritance
    let proto = Object.getPrototypeOf(field);
    while (proto) {
      if (proto.constructor?.name === 'MappingField') return true;
      proto = Object.getPrototypeOf(proto);
    }

    return false;
  }

  /**
   * Attempt to fix invalid document ID fields detected by Foundry validation and retry creation.
   * Foundry requires ID fields to match /^[a-zA-Z0-9]{16}$/. When the AI provides invalid IDs
   * (e.g. a folder name instead of a folder ID), we detect the validation error, correct the
   * fields, and retry the creation — reporting what was auto-corrected.
   * @param {Error} error - The original validation error from Foundry
   * @param {Object} parameters - The tool parameters (data is mutated in place)
   * @returns {Promise<Object|null>} Success response with warnings, or null if not an ID error
   */
  async #retryWithCorrectedIds(error, parameters) {
    const parsed = ValidationErrorHandler.parseFoundryValidationError(error);
    if (!parsed) return null;

    const ID_ERROR = '16-character alphanumeric';
    const corrections = [];

    for (const [fieldPath, detail] of Object.entries(parsed.details)) {
      if (!detail.error?.includes(ID_ERROR)) continue;

      const originalValue = this.#getFieldValue(parameters.data, fieldPath);
      let correctedValue;

      if (fieldPath === 'folder' || fieldPath.endsWith('.folder')) {
        // For folder fields: try to resolve by name, otherwise null (root level)
        correctedValue = this.#resolveFolderByName(originalValue, parameters.documentType);
      } else {
        // For other ID fields: remove and let Foundry auto-generate
        correctedValue = null;
      }

      this.#setFieldValue(parameters.data, fieldPath, correctedValue);
      corrections.push({ field: fieldPath, original: originalValue, corrected: correctedValue });
    }

    if (corrections.length === 0) return null;

    // Retry the creation with corrected data
    const { DocumentAPI } = await import('../core/document-api.js');
    let document;
    if (parameters.pack) {
      const documentClass = CONFIG[parameters.documentType]?.documentClass;
      document = await documentClass.create(parameters.data, { pack: parameters.pack });
    } else {
      document = await DocumentAPI.createDocument(parameters.documentType, parameters.data);
    }

    if (!document) return null;

    // Verify the created document
    const verificationOpts = { includeEmbedded: true };
    if (parameters.pack) verificationOpts.pack = parameters.pack;

    const fullDocument = await DocumentAPI.getDocument(
      parameters.documentType,
      document.id || document._id,
      verificationOpts
    );

    if (fullDocument) {
      documentReadRegistry.registerRead(
        parameters.documentType,
        fullDocument.id || fullDocument._id,
        fullDocument
      );
    }

    // Build correction warnings so the AI knows what was changed
    const warnings = corrections.map(c => {
      if (c.corrected === null) {
        return `Auto-corrected "${c.field}": invalid ID "${c.original}" was removed (set to null). Foundry document IDs must be exactly 16 alphanumeric characters.`;
      }
      return `Auto-corrected "${c.field}": invalid value "${c.original}" was resolved to folder ID "${c.corrected}".`;
    });

    const message = `Created @UUID[${parameters.documentType}.${fullDocument._id || fullDocument.id}]{${fullDocument.name || fullDocument._id}}`;
    const contentPayload = { message, document: fullDocument, warnings };

    return {
      content: JSON.stringify(contentPayload, null, 2),
      display: `Created **${fullDocument.name || fullDocument._id || fullDocument.id}** (${parameters.documentType})`,
      document: fullDocument,
    };
  }

  /**
   * Try to resolve a folder by name when an invalid ID was provided.
   * @param {string} value - The invalid folder value (might be a name)
   * @param {string} documentType - The document type to match folder type
   * @returns {string|null} Valid folder ID or null
   */
  #resolveFolderByName(value, documentType) {
    if (!value || typeof value !== 'string') return null;
    try {
      const folder = game.folders?.find(
        f => f.name?.toLowerCase() === value.toLowerCase() && f.type === documentType
      );
      return folder?.id ?? null;
    } catch {
      return null;
    }
  }

  /**
   * Get a value from an object by dot-separated field path.
   */
  #getFieldValue(obj, path) {
    const parts = path.split('.');
    let current = obj;
    for (const part of parts) {
      if (current == null) return undefined;
      current = current[part];
    }
    return current;
  }

  /**
   * Set a value on an object by dot-separated field path.
   */
  #setFieldValue(obj, path, value) {
    const parts = path.split('.');
    const last = parts.pop();
    let current = obj;
    for (const part of parts) {
      if (current[part] == null || typeof current[part] !== 'object') {
        current[part] = {};
      }
      current = current[part];
    }
    current[last] = value;
  }

  /**
   * Build a corrected example based on the agent's incorrect input
   * @param {string} documentType - The document type
   * @param {Object} unknownFieldsResult - Result from validateUnknownFields
   * @param {Object} DocumentAPI - The DocumentAPI module
   * @returns {Object} Schema response with message and schema object
   * @private
   */
  async #buildSchemaResponse(documentType, unknownFieldsResult, DocumentAPI) {
    const schema = DocumentAPI.getDocumentSchema(documentType);
    const embeddedSchemas = {};

    // Get schemas for all embedded document types
    if (schema?.embeddedSchemas) {
      for (const [fieldName, embeddedInfo] of Object.entries(schema.embeddedSchemas)) {
        // Get the actual embedded document type from the schema
        const embeddedType = schema.fieldDetails?.[fieldName]?.elementType;
        if (embeddedType) {
          const embeddedSchema = DocumentAPI.getDocumentSchema(embeddedType);
          if (embeddedSchema) {
            embeddedSchemas[fieldName] = {
              documentType: embeddedType,
              fields: embeddedSchema.fields,
              fieldDetails: embeddedSchema.fieldDetails,
            };
          }
        }
      }
    }

    // Build a compact but complete schema message
    let message = `Document creation rejected: Unknown fields would be silently discarded.\n\n`;
    message += `Unknown fields: ${unknownFieldsResult.unknownFields.join(', ')}\n\n`;
    message += `--- ${documentType} Schema ---\n`;
    message += `Valid top-level fields: ${schema?.fields?.join(', ') || 'none'}\n`;

    if (schema?.embedded?.length > 0) {
      message += `\nEmbedded document fields: ${schema.embedded.join(', ')}\n`;

      // Include the embedded document schemas
      for (const [fieldName, embeddedSchema] of Object.entries(embeddedSchemas)) {
        message += `\n--- ${embeddedSchema.documentType} Schema (for "${fieldName}" array) ---\n`;
        message += `Fields: ${embeddedSchema.fields?.join(', ') || 'none'}\n`;

        // Include field details for key fields
        if (embeddedSchema.fieldDetails) {
          const keyFields = ['name', 'type', 'text', 'content', 'system'];
          for (const key of keyFields) {
            const details = embeddedSchema.fieldDetails[key];
            if (details) {
              message += `  ${key}: ${details.type}`;
              if (details.required) message += ' (required)';
              if (details.choices) message += ` [${details.choices.join('|')}]`;
              if (details.nested) message += ` { ${Object.keys(details.nested).join(', ')} }`;
              message += '\n';
            }
          }
        }
      }
    }

    if (schema?.systemFields?.length > 0) {
      message += `\nSystem fields (inside "system"): ${schema.systemFields.join(', ')}\n`;
    }

    // Add specific guidance for the unknown fields
    message += `\n--- Guidance ---\n`;
    for (const suggestion of unknownFieldsResult.suggestions) {
      message += `• ${suggestion}\n`;
    }

    return {
      message,
      schema: {
        documentType,
        fields: schema?.fields,
        fieldDetails: schema?.fieldDetails,
        embedded: schema?.embedded,
        embeddedSchemas,
        systemFields: schema?.systemFields,
      },
    };
  }

  /**
   * Format document schema for inclusion in error messages.
   * Provides enough detail for the AI to self-correct without a separate schema tool call.
   * @param {string} documentType - The document type
   * @param {Object} schema - The schema from DocumentAPI.getDocumentSchema
   * @returns {string} Formatted schema information
   * @private
   */
  #formatSchemaForError(documentType, schema) {
    if (!schema) return '';

    let output = `--- ${documentType} Schema Reference ---\n`;
    output += `Top-level fields: ${schema.fields?.join(', ') || 'none'}\n`;

    if (schema.systemFields?.length > 0) {
      output += `System fields (inside "system"): ${schema.systemFields.join(', ')}\n`;
    }

    if (schema.embedded?.length > 0) {
      output += `Embedded documents: ${schema.embedded.join(', ')}\n`;
      // Add hints for common embedded collections
      if (schema.embedded.includes('JournalEntryPage')) {
        output += `  → JournalEntryPage goes in "pages" array: pages: [{ name: "...", type: "text", text: { content: "..." } }]\n`;
      }
      if (schema.embedded.includes('ActiveEffect')) {
        output += `  → ActiveEffect goes in "effects" array\n`;
      }
      if (schema.embedded.includes('Item')) {
        output += `  → Item goes in "items" array (for Actors)\n`;
      }
    }

    if (schema.systemFieldDetails && Object.keys(schema.systemFieldDetails).length > 0) {
      output += `Key system field structure:\n`;
      for (const [fieldName, details] of Object.entries(schema.systemFieldDetails)) {
        if (details.isCollection || details.isMapping || details.nested) {
          output += `  - system.${fieldName}: ${details.type}`;
          if (details.isCollection) output += ' (collection)';
          if (details.isMapping) output += ' (mapping - use object with ID keys)';
          output += '\n';
        }
      }
    }

    return output;
  }

  /**
   * Get example usage for this tool
   */
  getExamples() {
    return [
      {
        description: 'Create a new document (example)',
        parameters: {
          documentType: 'SomeDocumentType',
          name: 'Example Name',
          data: {
            content: '<p>Example content</p>',
          },
        },
      },
      {
        description: 'Create a typed document (example)',
        parameters: {
          documentType: 'SomeDocumentType',
          name: 'Example Entity',
          data: {
            type: 'some-type',
            img: 'icons/example.png',
            system: {
              details: { description: 'Example description' },
            },
          },
        },
      },
      {
        description: 'Create a document in a specific folder (example)',
        parameters: {
          documentType: 'SomeDocumentType',
          name: 'Example Object',
          folder: 'Compendium.foundryvtt.content-folder',
          data: {
            type: 'some-type',
            img: 'icons/example.svg',
            system: { uses: { value: 1, max: 1 } },
          },
        },
      },
    ];
  }

  /**
   * Get required permissions for this tool
   */
  getRequiredPermissions() {
    return {
      FILES_BROWSE: true,
      FILES_UPLOAD: true,
      DOCUMENT_CREATE: true,
      [`ENTITY_CREATE`]: true,
    };
  }
}

/**
 * Document Ownership Tool - Set ownership permissions on documents
 * Allows the AI to manage document permissions for players
 */

import { BaseTool } from './base-tool.js';
import { SimulacrumError } from '../utils/errors.js';
import { createLogger } from '../utils/logger.js';

const logger = createLogger('DocumentOwnershipTool');

/**
 * Foundry VTT ownership levels
 * @enum {number}
 */
const OWNERSHIP_LEVELS = {
  NONE: 0, // No access
  LIMITED: 1, // Limited access (can see name, basic info)
  OBSERVER: 2, // Can view but not edit
  OWNER: 3, // Full control
};

/**
 * Tool for setting document ownership permissions
 */
export class DocumentOwnershipTool extends BaseTool {
  constructor() {
    const schema = {
      type: 'object',
      properties: {
        document_type: {
          type: 'string',
          description:
            'The document class to set ownership on (e.g., "Actor", "Item", "JournalEntry", "Scene", "RollTable", "Playlist", "Macro", "Cards").',
        },
        document_id: {
          type: 'string',
          description: 'The ID of the document to set ownership for.',
        },
        ownership: {
          type: 'object',
          description:
            'An object mapping user IDs to permission levels (0-3). Use the "default" key to set the baseline for all players. Specific user IDs override the default (e.g., `{"default": 1, "userId123": 3}` gives one user full control and everyone else limited access).',
        },
      },
      required: ['document_type', 'document_id', 'ownership'],
    };

    super(
      'set_document_ownership',
      'Set ownership permissions for a document, controlling which players can view or edit it. Permission levels: 0 = None (hidden), 1 = Limited (name and basic info only), 2 = Observer (can view but not edit), 3 = Owner (full control). Use the "default" key in the ownership object to set the baseline for all players not explicitly listed.',
      schema,
      true // requiresConfirmation
    );
  }

  /**
   * Get parameter schema for this tool
   * @returns {Object} Parameter schema
   */
  getParameterSchema() {
    return this._addResponseParam(this.schema);
  }

  /**
   * Execute the ownership update
   * @param {Object} params - Tool parameters
   * @param {string} params.document_type - Document type
   * @param {string} params.document_id - Document ID
   * @param {Object} params.ownership - Ownership mapping
   * @returns {Promise<Object>} Result of the operation
   */
  async execute(params) {
    const { document_type, document_id, ownership } = params;

    // Validate parameters
    this.validateParameters(params, this.schema);

    // Security check: GM only
    if (!game.user?.isGM) {
      throw new SimulacrumError('Only GMs can set document ownership');
    }

    // Validate document type
    this.validateParams({ documentType: document_type });

    // Get the collection
    const collection = game.collections.get(document_type);
    if (!collection) {
      return this.handleError(`Invalid document type: "${document_type}"`, 'ValidationError');
    }

    // Get the document
    const doc = collection.get(document_id);
    if (!doc) {
      return this.handleError(
        `Document not found: "${document_id}" of type "${document_type}"`,
        'NotFoundError'
      );
    }

    // Validate ownership values
    if (!ownership || typeof ownership !== 'object') {
      return this.handleError(
        'Ownership must be an object mapping user IDs to permission levels',
        'ValidationError'
      );
    }

    const validationErrors = this._validateOwnershipObject(ownership);
    if (validationErrors.length > 0) {
      return this.handleError(
        `Invalid ownership values: ${validationErrors.join(', ')}`,
        'ValidationError'
      );
    }

    try {
      // Update the document
      await doc.update({ ownership });

      logger.info(`Ownership updated for ${document_type} "${doc.name}" (${document_id})`);

      // Build user-friendly ownership report
      const ownershipReport = this._buildOwnershipReport(doc.ownership);
      const reportLines = ownershipReport.map(r => `  ${r.user}: ${r.level_name}`).join('\n');

      const content = `Successfully updated ownership for "${doc.name}" (${document_type})\n${reportLines}`;
      const display = `Updated ownership for "${doc.name}"`;
      return this.createSuccessResponse(content, display);
    } catch (error) {
      return this.handleError(error.message, error.constructor.name);
    }
  }

  /**
   * Validate ownership object values
   * @param {Object} ownership - Ownership object to validate
   * @returns {Array<string>} Array of error messages
   * @private
   */
  _validateOwnershipObject(ownership) {
    const errors = [];
    const validLevels = Object.values(OWNERSHIP_LEVELS);

    for (const [key, value] of Object.entries(ownership)) {
      // Check if value is a valid ownership level
      if (!Number.isInteger(value) || !validLevels.includes(value)) {
        errors.push(`"${key}": ${value} is not a valid permission level (must be 0, 1, 2, or 3)`);
        continue;
      }

      // Check if key is 'default' or a valid user ID
      if (key !== 'default') {
        const user = game.users.get(key);
        if (!user) {
          errors.push(`"${key}": not a valid user ID or "default"`);
        }
      }
    }

    return errors;
  }

  /**
   * Build a human-readable ownership report
   * @param {Object} ownership - Ownership object
   * @returns {Array<Object>} Array of {user, level_name, level}
   * @private
   */
  _buildOwnershipReport(ownership) {
    const levelNames = ['None', 'Limited', 'Observer', 'Owner'];
    const report = [];

    for (const [userId, level] of Object.entries(ownership)) {
      if (userId === 'default') {
        report.push({
          user: 'Default (All Players)',
          user_id: 'default',
          level_name: levelNames[level] || 'Unknown',
          level,
        });
      } else {
        const user = game.users.get(userId);
        report.push({
          user: user?.name || 'Unknown User',
          user_id: userId,
          level_name: levelNames[level] || 'Unknown',
          level,
        });
      }
    }

    return report;
  }
}

/**
 * Document Search Tool - Search documents by content or metadata
 */

import { BaseTool } from './base-tool.js';
import { DocumentAPI } from '../core/document-api.js';

class DocumentSearchTool extends BaseTool {
  /**
   * Create a new Document Search Tool
   */
  constructor() {
    super(
      'search_documents',
      'Search for documents by matching a text query against document names, content, and metadata fields. Use this when you have a specific search term — for browsing all documents of a type without a query, use `list_documents` instead. Searches across all document types by default; use `documentTypes` to restrict scope.',
      {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description:
              'The text to search for. Matches against document names, text content, and metadata fields (e.g., "goblin", "fire damage", "healing potion").',
          },
          documentTypes: {
            type: 'array',
            items: { type: 'string' },
            description:
              'Restrict the search to specific document classes (e.g., ["Actor", "Item"]). Omit to search all types.',
          },
          fields: {
            type: 'array',
            items: { type: 'string' },
            description:
              'Restrict the search to specific document fields (e.g., ["name", "system.description.value"]). Omit to search all fields.',
          },
          pack: {
            type: 'string',
            description:
              'Restrict the search to a specific compendium pack (e.g., "dnd5e.monsters"). Omit to search the world and all packs.',
          },
        },
        required: ['query'],
      }
    );
  }

  /**
   * Execute the tool
   * @param {Object} params - Tool parameters
   * @returns {Object} Tool result
   */
  async execute(params) {
    try {
      const results = await DocumentAPI.searchDocuments({
        query: params.query,
        types: params.documentTypes,
        fields: params.fields,
        maxResults: params.maxResults,
        pack: params.pack,
      });

      const resultCount = results.length;
      const summary = `Found ${resultCount} document${resultCount !== 1 ? 's' : ''} matching "${params.query}"`;
      return {
        content: this.formatSearchResults(results, params.query),
        display: `<p><strong>${summary}</strong></p>`,
      };
    } catch (error) {
      return {
        content: 'Failed to search documents: ' + error.message,
        display: 'Search failed: ' + error.message,
        error: { message: error.message, type: 'SEARCH_FAILED' },
      };
    }
  }

  /**
   * Format search results for display
   * @param {Array} results - Search results
   * @param {string} query - Search query
   * @returns {string} Formatted results
   */
  formatSearchResults(results, query) {
    if (results.length === 0) {
      return 'No documents found matching "' + query + '"';
    }

    const formattedResults = results.map(doc => {
      const name = doc.name || doc.title || doc._id || 'Untitled';
      const id = doc.id || doc._id || 'Unknown ID';
      const type = doc.type || 'Unknown';
      let uuid = doc.uuid;

      // Construct UUID if missing
      if (!uuid) {
        if (doc.pack) {
          uuid = `Compendium.${doc.pack}.${id}`;
        } else {
          const docType = doc.documentName || doc.constructor?.documentName || type;
          // Basic heuristic if documentName isn't available on the result object
          if (docType) {
            uuid = `${docType}.${id}`;
          }
        }
      }

      if (uuid) {
        return `- @UUID[${uuid}]{${name}} (${type}, id: ${id})`;
      } else {
        return `- **${name}** (Type: ${type}, id: ${id})`;
      }
    });

    return '**Search Results for "' + query + '"**\n' + formattedResults.join('\n');
  }
}

export { DocumentSearchTool };

/**
 * Document Update Tool - Update documents of any type supported by current system
 */

import { BaseTool } from './base-tool.js';
import { DocumentAPI } from '../core/document-api.js';
import { ValidationErrorHandler } from '../utils/validation-errors.js';
import { createLogger, isDebugEnabled } from '../utils/logger.js';
import { DocumentUpdateLogic } from './document-update-logic.js';
import { ToolValidationError } from '../utils/tool-validation-error.js';
import { documentReadRegistry } from '../utils/document-read-registry.js';

class DocumentUpdateTool extends BaseTool {
  /**
   * Validate that the document has been read before modification
   * @param {string} documentType - Document type
   * @param {string} documentId - Document ID
   * @throws {Error} If document not read or stale
   */
  async #enforceReadBeforeModify(documentType, documentId, pack) {
    const opts = { includeEmbedded: true };
    if (pack) opts.pack = pack;
    const currentDoc = await DocumentAPI.getDocument(documentType, documentId, opts);
    if (!currentDoc) {
      const error = new Error(`Document @UUID[${documentType}.${documentId}] not found`);
      error.code = 'DOCUMENT_NOT_FOUND';
      throw error;
    }
    const currentData = currentDoc?.toObject?.() ?? currentDoc;
    documentReadRegistry.requireReadForModification(documentType, documentId, currentData);
  }

  constructor() {
    super(
      'update_document',
      'Update an existing document by merging field changes or performing array/embedded collection operations. The document must be read with `read_document` before it can be updated (stale-check enforced). Use `updates` for simple field changes with dot notation (e.g., `"system.hp.value": 25`). Use `operations` to insert, replace, or delete entries in arrays and embedded collections (e.g., pages, items, effects). Pass `documentType` as "Compendium" with `documentId` as the pack ID to configure pack settings (locked, folder, sort, ownership).',
      {
        type: 'object',
        properties: {
          documentType: {
            type: 'string',
            description:
              'The document class to update (e.g., Actor, Item, JournalEntry, RollTable, Scene).',
          },
          documentId: {
            type: 'string',
            description:
              'The ID of the document to update. The document must have been read first via `read_document`.',
          },
          updates: {
            type: 'object',
            description:
              'An object of field paths and values to merge into the document. Supports dot notation for nested fields (e.g., `{"system.hp.value": 25, "name": "New Name"}`). Use this for simple field changes.',
            additionalProperties: true,
          },
          operations: {
            type: 'array',
            description:
              'An ordered list of mutations for arrays and embedded collections. Use this instead of `updates` when adding, replacing, or removing entries in collections like pages, items, or effects.',
            items: {
              type: 'object',
              properties: {
                action: {
                  type: 'string',
                  enum: ['insert', 'replace', 'delete'],
                  description:
                    'The mutation to perform: "insert" adds a new entry, "replace" overwrites an existing entry, "delete" removes an entry.',
                },
                path: {
                  type: 'string',
                  description:
                    'The dot-notation path to the target array or embedded collection (e.g., "pages", "items", "effects", "system.activities").',
                },
                index: {
                  type: 'integer',
                  description:
                    'The 0-based position for plain array operations. Required for insert/replace/delete on arrays.',
                },
                id: {
                  type: 'string',
                  description:
                    'The ID of the embedded document to target. Required for replace/delete on embedded collections (pages, items, effects).',
                },
                value: {
                  type: 'object',
                  description:
                    'The data object to insert or replace with. Not needed for delete operations.',
                },
              },
              required: ['action', 'path'],
            },
          },
          pack: {
            type: 'string',
            description:
              'The compendium pack ID if updating a document inside a compendium (e.g., "simulacrum.simulacrum-tools"). The pack must be unlocked first (use `update_document` with `documentType="Compendium"` to unlock). Omit to update in the world.',
          },
        },
        required: ['documentType', 'documentId'],
      },
      true
    );
    this.logger = createLogger('DocumentUpdateTool');
  }

  // eslint-disable-next-line no-unused-vars
  getConfirmationDetails(params) {
    return {
      title: `Update ${params.documentType}`,
      html: `
        <div class="simulacrum-confirmation">
          <p><strong>Type:</strong> ${params.documentType}</p>
          <p><strong>ID:</strong> ${params.documentId}</p>
          <div class="code-preview">
            ${params.updates ? `<strong>Updates:</strong><pre>${JSON.stringify(params.updates, null, 2)}</pre>` : ''}
            ${params.operations ? `<strong>Operations:</strong><pre>${JSON.stringify(params.operations, null, 2)}</pre>` : ''}
          </div>
        </div>
      `,
    };
  }

  /**
   * Execute the tool
   * @param {Object} params - Tool parameters
   * @returns {Object} Tool result
   */
  async execute(params) {
    if (isDebugEnabled()) {
      this.logger.info('Starting execute with params:', params);
    }
    const normalizedParams = { ...params };
    if (typeof normalizedParams.documentId === 'string') {
      normalizedParams.documentId = BaseTool.extractRawId(normalizedParams.documentId.trim());
    }

    try {
      // Compendium configure branch — early return before normal document flow
      if (normalizedParams.documentType === 'Compendium') {
        return this._configureCompendium(normalizedParams);
      }

      this._validateBasicParams(normalizedParams);
      const { documentType, documentId, pack } = normalizedParams;

      // Check if pack is locked before attempting update
      if (pack) {
        const packCollection = game.packs.get(pack);
        if (!packCollection) {
          return {
            content: `Compendium pack "${pack}" not found`,
            display: `Pack not found: ${pack}`,
            error: { message: `pack "${pack}" not found`, type: 'PACK_NOT_FOUND' },
          };
        }
        if (packCollection.locked) {
          return {
            content: `Compendium pack "${pack}" is locked. Use update_document with documentType="Compendium" to unlock it first.`,
            display: `Pack is locked: ${pack}`,
            error: { message: `pack "${pack}" is locked`, type: 'PACK_LOCKED' },
          };
        }
        if (packCollection.documentName !== documentType) {
          return {
            content: `Pack "${pack}" contains ${packCollection.documentName} documents, but you specified ${documentType}`,
            display: `Type mismatch: Pack contains ${packCollection.documentName}`,
            error: { message: `Type mismatch`, type: 'TYPE_MISMATCH' },
          };
        }
      }

      await this.#enforceReadBeforeModify(documentType, documentId, pack);

      // Validate images — invalid ones are blanked, not rejected
      if (normalizedParams.updates) await this.validateImageUrls(normalizedParams.updates);
      if (normalizedParams.operations) await this.validateImageUrls(normalizedParams.operations);

      // Correct malformed UUIDs using schema-derived reference fields
      if (normalizedParams.updates)
        this.validateUuids(documentType, normalizedParams.updates, pack);
      if (normalizedParams.operations)
        this.validateUuids(documentType, normalizedParams.operations, pack);

      const plan = await this.#buildOperationPlan(normalizedParams);
      const { updates, embeddedOperations } = plan;

      if (Object.keys(updates).length === 0 && embeddedOperations.length === 0) {
        throw new ToolValidationError('No updates provided. Supply `updates` or `operations`.');
      }

      await this.#applyOperations(normalizedParams, updates, embeddedOperations);

      return await this.#buildSuccessResponse(normalizedParams);
    } catch (error) {
      return this.#handleExecuteError(error, normalizedParams);
    }
  }

  /**
   * Configure a compendium pack (lock/unlock, folder, sort, ownership)
   * @param {Object} params - Tool parameters with documentId as pack ID, updates as config fields
   * @returns {Promise<Object>} Configuration result
   */
  async _configureCompendium(params) {
    const { documentId, updates } = params;

    if (!game.user?.isGM) {
      return {
        content: 'Only GMs can configure compendium packs',
        display: 'Permission denied: GM required',
        error: { message: 'Only GMs can configure compendium packs', type: 'PERMISSION_DENIED' },
      };
    }

    if (typeof documentId !== 'string' || documentId === '') {
      return {
        content: 'Parameter "documentId" must be a non-empty pack ID (e.g., "world.my-pack")',
        display: 'Missing documentId',
        error: { message: 'documentId is required', type: 'VALIDATION_ERROR' },
      };
    }

    const pack = game.packs.get(documentId);
    if (!pack) {
      return {
        content: `Compendium pack "${documentId}" not found`,
        display: `Pack not found: ${documentId}`,
        error: { message: `Pack "${documentId}" not found`, type: 'PACK_NOT_FOUND' },
      };
    }

    if (!updates || typeof updates !== 'object' || Object.keys(updates).length === 0) {
      return {
        content:
          'Provide `updates` with compendium config fields: `locked` (boolean), `folder` (string|null), `sort` (number), `ownership` (object mapping role names to permission level names).',
        display: 'No updates provided',
        error: { message: 'No updates provided', type: 'VALIDATION_ERROR' },
      };
    }

    // Only pass through fields that CompendiumCollection.configure() accepts
    const allowedFields = ['locked', 'folder', 'sort', 'ownership'];
    const configData = {};
    for (const key of allowedFields) {
      if (key in updates) {
        configData[key] = updates[key];
      }
    }

    if (Object.keys(configData).length === 0) {
      return {
        content: `No valid compendium config fields in updates. Accepted fields: ${allowedFields.join(', ')}`,
        display: 'No valid config fields',
        error: { message: 'No valid config fields', type: 'VALIDATION_ERROR' },
      };
    }

    try {
      await pack.configure(configData);
      const label = pack.metadata.label;
      const summary = Object.entries(configData)
        .map(([k, v]) => `${k}=${JSON.stringify(v)}`)
        .join(', ');
      const msg = `Configured compendium "${label}" (${documentId}): ${summary}`;
      return {
        content: JSON.stringify({ message: msg, packId: documentId, applied: configData }, null, 2),
        display: `Configured **${label}** (${summary})`,
      };
    } catch (error) {
      return {
        content: `Failed to configure compendium: ${error.message}`,
        display: `Configuration failed: ${error.message}`,
        error: { message: error.message, type: 'CONFIGURE_FAILED' },
      };
    }
  }

  #handleExecuteError(error, params) {
    if (isDebugEnabled()) this.logger.info('Caught error in execute():', error.name, error.message);
    if (error instanceof ToolValidationError) {
      return this.#buildValidationErrorResponse(error.message, params);
    }
    const readErrors = ['DOCUMENT_NOT_READ', 'DOCUMENT_STALE', 'DOCUMENT_NOT_FOUND'];
    if (readErrors.includes(error.code)) {
      return {
        content: error.message,
        display: `${error.message}`,
        error: {
          message: error.message,
          type: error.code,
          documentType: params.documentType,
          documentId: params.documentId,
        },
      };
    }
    return ValidationErrorHandler.createToolErrorResponse(
      error,
      'update',
      params.documentType,
      params.documentId
    );
  }

  _validateBasicParams(params) {
    if (!this.isValidDocumentType(params.documentType)) {
      throw new ToolValidationError(
        `Document type "${params.documentType}" not available in current system`
      );
    }
    if (typeof params.documentId !== 'string' || params.documentId === '') {
      throw new ToolValidationError('Parameter "documentId" must be a non-empty string');
    }
  }

  async #applyOperations(params, updates, embeddedOperations) {
    if (embeddedOperations.length) {
      if (isDebugEnabled()) this.logger.info('Applying embedded operations:', embeddedOperations);
      await DocumentAPI.applyEmbeddedOperations(
        params.documentType,
        params.documentId,
        embeddedOperations
      );
    }

    if (Object.keys(updates).length) {
      if (isDebugEnabled())
        this.logger.info('Calling DocumentAPI.updateDocument() with updates:', updates);
      await DocumentAPI.updateDocument(params.documentType, params.documentId, updates, {
        pack: params.pack,
      });
    }
  }

  async #buildSuccessResponse(params) {
    const opts = { includeEmbedded: true };
    if (params.pack) opts.pack = params.pack;
    const latestDocument = await DocumentAPI.getDocument(
      params.documentType,
      params.documentId,
      opts
    );
    const id = latestDocument.name || latestDocument._id || latestDocument.id;

    // Update the registry with the new document state so subsequent edits don't fail
    const data =
      typeof latestDocument?.toObject === 'function' ? latestDocument.toObject() : latestDocument;
    documentReadRegistry.registerRead(params.documentType, params.documentId, data);

    return {
      content: JSON.stringify(
        {
          message: `Updated @UUID[${params.documentType}.${params.documentId}]`,
          document: latestDocument,
        },
        null,
        2
      ),
      display: `Updated **${id}** (${params.documentType})`,
      document: latestDocument,
    };
  }

  async #buildOperationPlan(params) {
    const flatUpdates = this.#normalizeUpdates(params.updates);
    const operations = params.operations;
    const embeddedOperations = [];
    let remainingUpdates = { ...flatUpdates };
    const embeddedState = new Map();

    const requiresDocument =
      Object.keys(flatUpdates || {}).length || (Array.isArray(operations) && operations.length);

    let workingDocument = {};
    let docInstance = null;

    if (requiresDocument) {
      if (isDebugEnabled()) this.logger.info('Fetching document for operations');
      const documentSnapshot = await DocumentAPI.getDocument(
        params.documentType,
        params.documentId,
        { includeEmbedded: true, pack: params.pack }
      );
      workingDocument = DocumentUpdateLogic.cloneValue(documentSnapshot);
      // Note: getDocumentInstance might not support pack yet? check API.
      // Re-checked API: getDocumentInstance looks like it only supports collections.
      // However, for updates (merging objects), workingDocument (snapshot) is the most critical part.
      // docInstance is used for isEmbeddedCollection checks.
      // Ideally we shouldn't fail if docInstance is missing for compendium?
      // Or we should update getDocumentInstance too?
      // For now, let's try to fetch it, but if it fails (because it only looks in collections),
      // we might have issues with embedded operations logic.
      // But standard updates rely on workingDocument.

      // Let's modify getDocumentInstance call or accept that embedded logic might be limited for packs.
      // Actually DocumentAPI.getDocumentInstance logic is: Resolves collection -> collection.get().
      // So it strictly requires World collection.
      // We should probably skip getDocumentInstance for packs and rely on schema introspection if possible,
      // OR update DocumentAPI to return a dummy instance or the real one if Pack supports it.
      // Pack.getDocument(id) returns a Document instance!

      // FIX: We need to bypass DocumentAPI.getDocumentInstance for packs if it doesn't support them,
      // or duplicate the packing logic there.
      // Since I can't easily modify DocumentAPI again right now to add getDocumentInstance pack support without risking more scope creep,
      // I will conditionally fetch the instance directly from the pack if pack is present.

      if (params.pack) {
        const packObj = game.packs.get(params.pack);
        if (packObj) {
          docInstance = await packObj.getDocument(params.documentId);
        }
      } else {
        docInstance = await DocumentAPI.getDocumentInstance(params.documentType, params.documentId);
      }

      const extraction = DocumentUpdateLogic.extractEmbeddedFieldUpdates(
        remainingUpdates,
        docInstance,
        embeddedState
      );
      remainingUpdates = extraction.remainingUpdates;
      embeddedOperations.push(...extraction.embeddedOperations);
    }

    if (operations?.length) {
      if (!Array.isArray(operations)) {
        throw new ToolValidationError('Parameter "operations" must be an array when provided');
      }
      const opResults = this.#processOperations({
        operations,
        docInstance,
        workingDocument,
        embeddedState,
        embeddedOperations,
      });
      remainingUpdates = { ...remainingUpdates, ...opResults };
    }

    return { updates: remainingUpdates, embeddedOperations };
  }

  #processOperations({
    operations,
    docInstance,
    workingDocument,
    embeddedState,
    embeddedOperations,
  }) {
    const operationResults = {};
    for (let index = 0; index < operations.length; index += 1) {
      const normalized = DocumentUpdateLogic.normalizeOperation(operations[index], index);
      const segments = normalized.path.split('.');
      const collectionKey = segments[0];

      if (docInstance && DocumentUpdateLogic.isEmbeddedCollection(docInstance, collectionKey)) {
        const embeddedOp = DocumentUpdateLogic.prepareEmbeddedOperation(normalized, {
          docInstance,
          collectionKey,
          operationIndex: index,
          embeddedState,
        });
        embeddedOperations.push(embeddedOp);
      } else {
        const currentValue = this.#getValueAtPath(workingDocument, normalized.path);
        if (!Array.isArray(currentValue)) {
          throw new ToolValidationError(
            `Operation ${index + 1}: path "${normalized.path}" does not reference an array`
          );
        }
        const updatedArray = DocumentUpdateLogic.performArrayOperation(
          currentValue,
          normalized,
          index
        );
        this.#setValueAtPath(workingDocument, normalized.path, updatedArray);
        operationResults[normalized.path] = updatedArray;
      }
    }
    return operationResults;
  }

  #normalizeUpdates(updates) {
    if (updates === undefined) return {};
    if (updates === null || typeof updates !== 'object' || Array.isArray(updates)) {
      throw new ToolValidationError('Parameter "updates" must be an object when provided');
    }
    return { ...updates };
  }

  #getValueAtPath(target, path) {
    const segments = path.split('.');
    let current = target;
    for (const segment of segments) {
      if (current === null || current === undefined) return undefined;
      current = current[segment];
    }
    return current;
  }

  #setValueAtPath(target, path, value) {
    const segments = path.split('.');
    const lastSegment = segments.pop();
    let current = target;
    for (const segment of segments) {
      if (!current[segment] || typeof current[segment] !== 'object') {
        current[segment] = {};
      }
      current = current[segment];
    }
    current[lastSegment] = value;
  }

  #buildValidationErrorResponse(message, params) {
    const docRef =
      params.documentType && params.documentId
        ? `@UUID[${params.documentType}.${params.documentId}]`
        : params.documentType || 'document';

    return {
      content: `Validation failed for update ${docRef}: ${message}`,
      display: `Validation Error: ${message}`,
      error: {
        message,
        type: 'VALIDATION_ERROR',
        documentType: params.documentType,
        documentId: params.documentId,
      },
    };
  }
}

export { DocumentUpdateTool };

import { BaseTool } from './base-tool.js';
import { SimulacrumHooks } from '../core/hook-manager.js';

export class ManageTaskTool extends BaseTool {
  constructor() {
    super(
      'manage_task',
      'Track progress on multi-step tasks with a visual step tracker shown to the user. Call with "start_task" to define a task with named steps, "update_task" to advance to each step as you work, and "finish_task" to complete the task with a summary. The final step in every task must have the title "Summary".',
      {
        type: 'object',
        properties: {
          action: {
            type: 'string',
            enum: ['start_task', 'update_task', 'finish_task'],
            description:
              'The lifecycle action: "start_task" creates a new task with a name, goal, and step list. "update_task" advances to a step and reports progress. "finish_task" completes the task and displays a summary.',
          },
          taskName: {
            type: 'string',
            description: 'The display name for the task (required for start_task).',
          },
          taskGoal: {
            type: 'string',
            description:
              'A brief description of what the task aims to accomplish (required for start_task).',
          },
          steps: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                title: {
                  type: 'string',
                  description:
                    'A short label for the step (e.g., "Research", "Implement", "Verify", "Summary").',
                },
                description: {
                  type: 'string',
                  description: 'A description of what this step accomplishes.',
                },
              },
              required: ['title', 'description'],
            },
            description:
              'The ordered list of steps for the task (required for start_task). Each step has a `title` and `description`. The last step must have title "Summary".',
          },
          currentStep: {
            type: 'integer',
            description:
              'The 0-indexed step number to advance to (for update_task). All steps before this index are marked completed.',
          },
          status: {
            type: 'string',
            description:
              'A human-readable progress message for the current step (e.g., "Researching existing documents", "Creating the NPC actor"). Do not use machine-style values like "in_progress" or "completed".',
          },
          summary: {
            type: 'string',
            description:
              'A concise summary of what was accomplished (required for finish_task). This text is displayed as the final Summary step content.',
          },
        },
        required: ['action'],
      }
    );

    this.currentTask = null;
  }

  async execute(params) {
    const { action } = params;

    if (action === 'start_task') {
      return this._startTask(params);
    }

    if (action === 'update_task') {
      return this._updateTask(params);
    }

    if (action === 'finish_task') {
      return this._finishTask(params);
    }
  }

  _startTask({ taskName, taskGoal, steps }) {
    if (!taskName || !taskGoal || !steps) {
      return this.handleError(
        'start_task requires taskName, taskGoal, and steps.',
        'ValidationError'
      );
    }

    // Validate step structure
    if (!Array.isArray(steps) || steps.length === 0) {
      return this.handleError(
        'Task rejected: steps must be a non-empty array of {title, description} objects.',
        'ValidationError'
      );
    }

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      if (!step || typeof step.title !== 'string' || typeof step.description !== 'string') {
        return this.handleError(
          `Task rejected: Step ${i} must be an object with "title" and "description" string properties.`,
          'ValidationError'
        );
      }
    }

    // Validate that the final step is a Summary step
    const lastStep = steps[steps.length - 1];
    if (lastStep.title !== 'Summary') {
      return this.handleError(
        'Task rejected: The final step must have title "Summary". ' +
          'Please restructure your task list so the last step is { title: "Summary", description: "<placeholder or actual summary>" }.',
        'ValidationError'
      );
    }

    this.currentTask = {
      name: taskName,
      goal: taskGoal,
      steps: steps.map(s => ({ title: s.title, description: s.description, status: 'pending' })),
      currentStepIndex: 0,
      startTime: Date.now(),
      lastDisplayedStep: 0, // Track which step we last showed a separator for (started at 0)
    };

    // Mark first step as in progress
    this.currentTask.steps[0].status = 'in_progress';

    // Emit hook to show task tracker
    Hooks.callAll(SimulacrumHooks.TASK_STARTED, this._getTaskState());

    // Generate separator for Step 1 immediately
    const stepNum = 1;
    const currentStepTitle = steps[0].title;
    const separatorHtml = `<div class="simulacrum-step-separator"><div class="step-task-name">${taskName}</div><div class="step-info"><span class="step-label">Step ${stepNum}</span><span class="step-title">${currentStepTitle}</span></div></div>`;

    return {
      content: `Task started: ${taskName}\nGoal: ${taskGoal}\nSteps: ${steps.length}`,
      display: separatorHtml,
    };
  }

  _updateTask({ currentStep, status }) {
    if (!this.currentTask) return { content: 'No active task to update.', display: '' };

    if (typeof currentStep === 'number') {
      this.currentTask.currentStepIndex = currentStep;
      // Mark previous steps done
      for (let j = 0; j < currentStep; j++) {
        this.currentTask.steps[j].status = 'completed';
      }
      // Mark current step in progress
      if (this.currentTask.steps[currentStep]) {
        this.currentTask.steps[currentStep].status = 'in_progress';
      }
    }

    // Emit hook to update task tracker
    Hooks.callAll(SimulacrumHooks.TASK_UPDATED, this._getTaskState());

    const currentStepTitle =
      this.currentTask.steps[this.currentTask.currentStepIndex]?.title || 'Unknown';
    const stepNum = this.currentTask.currentStepIndex + 1;
    const totalSteps = this.currentTask.steps.length;
    const taskName = this.currentTask.name;

    // Only show separator when moving to a NEW step (prevents duplicates when AI calls update_task multiple times)
    const stepIndex = this.currentTask.currentStepIndex;
    const isNewStep = stepIndex !== this.currentTask.lastDisplayedStep;

    let display = '';
    if (isNewStep) {
      this.currentTask.lastDisplayedStep = stepIndex;
      display = `<div class="simulacrum-step-separator"><div class="step-task-name">${taskName}</div><div class="step-info"><span class="step-label">Step ${stepNum}</span><span class="step-title">${currentStepTitle}</span></div></div>`;
    }

    return {
      content: `Task update: Step ${stepNum}/${totalSteps} - ${currentStepTitle}`,
      display,
    };
  }

  _finishTask({ summary }) {
    if (!this.currentTask) return { content: 'No active task to finish.', display: '' };

    // Require summary content for finish_task
    if (!summary || typeof summary !== 'string' || summary.trim().length === 0) {
      return this.handleError(
        'finish_task rejected: You MUST provide a "summary" parameter describing what was accomplished. ' +
          'Example: { action: "finish_task", summary: "Deleted the accidental human race item and updated the Shym races journal with all canonical FR 2e races." }',
        'ValidationError'
      );
    }

    // Update the Summary step's description with the actual summary content
    const lastStepIndex = this.currentTask.steps.length - 1;
    this.currentTask.steps[lastStepIndex].description = summary;

    // Mark all steps as completed
    this.currentTask.steps.forEach(s => {
      s.status = 'completed';
    });

    const taskName = this.currentTask.name;

    // Emit hook to hide task tracker
    Hooks.callAll(SimulacrumHooks.TASK_FINISHED, {
      ...this._getTaskState(),
      summary: summary,
    });

    this.currentTask = null;

    return {
      content: `Task completed: ${taskName}\n\nSummary: ${summary}`,
      display: `**Task Complete: ${taskName}**\n\n${summary}`,
    };
  }

  _getTaskState() {
    if (!this.currentTask) return null;
    return {
      name: this.currentTask.name,
      goal: this.currentTask.goal,
      steps: this.currentTask.steps.map(s => ({ ...s })),
      currentStepIndex: this.currentTask.currentStepIndex,
      totalSteps: this.currentTask.steps.length,
    };
  }
}

