 */
export function registerSettingsEnhancements() {
  Hooks.on('renderSettingsConfig', (app, html, _data) => {
    setTimeout(() => {
      try {
        _applyEnhancements(html);
      } catch (error) {
        createLogger('Settings').error('Error in settings render:', error);
      }
    }, 100);
  });
}

function _applyEnhancements(html) {
  // Ensure html is a jQuery object for consistent API usage (ApplicationV2 may pass HTMLElement)
  const $html = html instanceof jQuery ? html : $(html);

  const style =
    'width: 518px; min-height: 80px; height: 120px; white-space: normal; word-wrap: break-word;';
  const callback = settingDiv => {
    const notesEl = settingDiv.find('p.notes');
    const formFieldsEl = settingDiv.find('div.form-fields');
    if (notesEl.length && formFieldsEl.length) {
      notesEl.after(formFieldsEl);
    }
  };

  convertSettingToTextarea({
    html: $html,
    moduleId: 'simulacrum',
    settingKey: 'customSystemPrompt',
    textareaStyle: style,
    repositionCallback: callback,
  });

  // Add Discord link to Simulacrum settings tab
  _addDiscordLink($html);

  $html.find('a.item[data-tab="simulacrum"]').on('click', () => {
    setTimeout(() => {
      // Check if input exists and hasn't been converted to textarea yet
      if ($html.find('input[name="simulacrum.customSystemPrompt"]').length) {
        convertSettingToTextarea({
          html: $html,
          moduleId: 'simulacrum',
          settingKey: 'customSystemPrompt',
          textareaStyle: style,
          repositionCallback: callback,
        });
      }
      // Re-add Discord link when tab is clicked (in case it was re-rendered)
      _addDiscordLink($html);
    }, 500);
  });
}

function _addDiscordLink($html) {
  // Try both section and div for V12/V13 compatibility
  let simulacrumTab = $html.find('section[data-tab="simulacrum"]');
  if (!simulacrumTab.length) {
    simulacrumTab = $html.find('div[data-tab="simulacrum"]');
  }
  if (!simulacrumTab.length) return;

  // Don't add if already present
  if (simulacrumTab.find('.simulacrum-discord-link').length) return;

  const discordHtml = `
    <div class="form-group simulacrum-discord-link">
      <label>Join our community</label>
      <div class="form-fields">
        <button type="button" class="discord-btn" onclick="window.open('https://discord.gg/VSs8jZBgmP', '_blank')">
          <i class="fab fa-discord"></i>
          <span>Discord</span>
        </button>
      </div>
    </div>
  `;

  simulacrumTab.prepend(discordHtml);
}

/**
 * Tool Permissions Configuration - ApplicationV2 for managing destructive tool permissions
 * Uses the modern Foundry V13 HandlebarsApplicationMixin pattern
 */

import { createLogger } from '../utils/logger.js';
import { toolPermissionManager, PermissionState } from '../core/tool-permission-manager.js';

const logger = createLogger('ToolPermissionsConfig');

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

/**
 * ApplicationV2 for configuring tool permissions
 * Allows users to set per-tool permission states (ask/allow/deny)
 * @extends ApplicationV2
 * @mixes HandlebarsApplication
 */
export class ToolPermissionsConfig extends HandlebarsApplicationMixin(ApplicationV2) {
  /** @inheritDoc */
  static DEFAULT_OPTIONS = {
    id: 'simulacrum-tool-permissions',
    tag: 'form',
    window: {
      contentClasses: ['standard-form'],
      icon: 'fa-solid fa-shield-halved',
      title: 'SIMULACRUM.ToolPermissionsConfig.Title',
    },
    position: { width: 500, height: 640 },
    form: {
      closeOnSubmit: true,
      handler: ToolPermissionsConfig.#onSubmit,
    },
    actions: {
      reset: ToolPermissionsConfig.#onReset,
    },
  };

  /** @override */
  static PARTS = {
    form: {
      id: 'form',
      template: 'modules/simulacrum/templates/tool-permissions-config.hbs',
      root: true,
      scrollable: ['.scrollable'],
    },
    footer: {
      template: 'templates/generic/form-footer.hbs',
    },
  };

  /* -------------------------------------------- */
  /*  Rendering                                   */
  /* -------------------------------------------- */

  /** @override */
  async _prepareContext(_options = {}) {
    const allTools = toolPermissionManager.getAllDestructiveTools();
    const trustAllEnabled = toolPermissionManager.isTrustAllEnabled();

    // Separate static destructive tools from dynamic macro tools
    const staticTools = allTools.filter(t => t.isStatic);
    const macroTools = allTools.filter(t => !t.isStatic);

    // Build permission choices for dropdowns
    const permissionChoices = {
      [PermissionState.ASK]: game.i18n.localize(
        'SIMULACRUM.Settings.ToolPermissions.PermissionState.Ask'
      ),
      [PermissionState.ALLOW]: game.i18n.localize(
        'SIMULACRUM.Settings.ToolPermissions.PermissionState.Allow'
      ),
      [PermissionState.DENY]: game.i18n.localize(
        'SIMULACRUM.Settings.ToolPermissions.PermissionState.Deny'
      ),
    };

    return {
      trustAllEnabled,
      trustAllWarning: game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.TrustAllWarning'),
      staticTools: staticTools.map(tool => ({
        ...tool,
        isAsk: tool.permission === PermissionState.ASK,
        isAllow: tool.permission === PermissionState.ALLOW,
        isDeny: tool.permission === PermissionState.DENY,
      })),
      macroTools: macroTools.map(tool => ({
        ...tool,
        isAsk: tool.permission === PermissionState.ASK,
        isAllow: tool.permission === PermissionState.ALLOW,
        isDeny: tool.permission === PermissionState.DENY,
      })),
      permissionChoices,
      hasMacroTools: macroTools.length > 0,
      labels: {
        destructiveTools: game.i18n.localize(
          'SIMULACRUM.Settings.ToolPermissions.DestructiveTools'
        ),
        macroTools: game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.MacroTools'),
        noMacroTools: game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.NoMacroTools'),
      },
      buttons: [
        {
          type: 'reset',
          action: 'reset',
          icon: 'fa-solid fa-arrows-rotate',
          label: 'SIMULACRUM.Settings.ToolPermissions.ResetDefaults',
        },
        { type: 'submit', icon: 'fa-solid fa-floppy-disk', label: 'SIMULACRUM.Settings.Save' },
      ],
    };
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /**
   * Handle form submission - save permission changes
   * @this {ToolPermissionsConfig}
   * @param {SubmitEvent} event - Submit event
   * @param {HTMLFormElement} form - The form element
   * @param {FormDataExtended} formData - Processed form data
   */
  static async #onSubmit(event, form, formData) {
    logger.info('Saving tool permissions:', formData.object);

    const data = formData.object;
    const permissions = {};

    // Handle Trust All setting
    const trustAllEnabled = !!data.trustAllTools;
    await game.settings.set('simulacrum', 'trustAllTools', trustAllEnabled);

    // Process each tool permission from form data
    for (const [key, value] of Object.entries(data)) {
      if (key.startsWith('permission_')) {
        const toolName = key.replace('permission_', '');

        // Only store non-default permissions
        if (value !== PermissionState.ASK) {
          permissions[toolName] = value;
        }
      }
    }

    // Save permissions
    await game.settings.set('simulacrum', 'toolPermissions', permissions);

    logger.info('Tool permissions saved:', permissions);
    ui.notifications.info(
      game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.Saved') || 'Tool permissions saved.'
    );
  }

  /**
   * Handle reset button click
   * @this {ToolPermissionsConfig}
   * @param {PointerEvent} event - The click event
   * @param {HTMLElement} target - The button element
   */
  static async #onReset(event, target) {
    const confirmed = await foundry.applications.api.DialogV2.confirm({
      window: { title: game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.ResetDefaults') },
      content: `<p>${game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.ResetConfirm') || 'Are you sure you want to reset all tool permissions to their default values (Ask Each Time)?'}</p>`,
      yes: { default: true },
    });

    if (confirmed) {
      // Clear all stored permissions
      await game.settings.set('simulacrum', 'toolPermissions', {});
      await game.settings.set('simulacrum', 'trustAllTools', false);
      ui.notifications.info(
        game.i18n.localize('SIMULACRUM.Settings.ToolPermissions.ResetSuccess') ||
          'Tool permissions reset to defaults.'
      );
      this.render();
    }
  }
}

/**
 * Smart slicing for message arrays to preserve tool call dependencies.
 * @module utils/message-utils
 */

/**
 * Smartly slice messages to enforce a token/count limit while preserving dependencies.
 * specifically ensuring that tool results are never orphaned from their parent assistant calls.
 *
 * @param {Array<object>} messages - The array of messages to slice
 * @param {number} limit - The maximum number of messages to return (soft limit)
 * @returns {Array<object>} The sliced messages, potentially slightly larger than limit to preserve context
 */
export function smartSliceMessages(messages, limit) {
  if (!Array.isArray(messages) || messages.length === 0) return [];
  if (limit <= 0) return [];
  if (messages.length <= limit) return messages;

  // Initial naive slice
  // const startIndex = messages.length - limit;
  // let sliced = messages.slice(-limit);

  let startIndex = messages.length - limit;
  if (startIndex < 0) startIndex = 0;

  // Check if the cut point splits a dependency
  // If the first message in our slice is a TOOL result, we must find its parent.
  // We look backwards from startIndex - 1.
  let currentStart = startIndex;

  // Safety loop to prevent infinite recursion in malformed history, though highly unlikely
  // We only look back a reasonable amount (e.g. 5 steps) to find the parent.
  const MAX_LOOKBACK = 10;
  let attempts = 0;

  while (
    currentStart > 0 &&
    currentStart < messages.length &&
    messages[currentStart].role === 'tool' &&
    attempts < MAX_LOOKBACK
  ) {
    const toolMsg = messages[currentStart];
    const toolCallId = toolMsg.tool_call_id;

    // Look for the parent assistant message
    let foundParent = false;
    for (let i = currentStart - 1; i >= 0 && i >= startIndex - MAX_LOOKBACK; i--) {
      const candidate = messages[i];
      if (candidate.role === 'assistant' && candidate.tool_calls) {
        const hasCall = candidate.tool_calls.some(tc => tc.id === toolCallId);
        if (hasCall) {
          // Found the parent!
          // We must include this parent index.
          currentStart = i;
          foundParent = true;
          break;
        }
      }
    }

    if (!foundParent) {
      // If we can't find the parent within lookback, we can't save it.
      // But maybe the message before it is another tool result from the SAME parent?
      // In that case, we should keep going back.
      // For now, if we don't find a parent, we just stop expanding to avoid pulling in the whole history.
      // Better to have an orphan than 1000 tokens? Logic says NO, an orphan crashes the API.
      // So if we have an orphan, we should actually DISCARD the tool result if we can't find the parent.
      // But adhering to "Smart Slice" usually means "Expand to include context".
      // Let's just break if not found.
      break;
    }
    attempts++;
  }

  return messages.slice(currentStart);
}

/**
 * Format a tool call result as rich HTML with status icons
 * @param {Object} toolResult - The tool result object/message
 * @param {string} toolName - The name of the tool (must be provided as it might not be in the message)
 * @returns {string} HTML string for display
 */
/**
 * Extracts just the raw display content string from a tool result, without wrapping it in HTML.
 * @param {object} toolResult - The tool result object
 * @returns {string|null} The raw string content or null if not found
 */
export function getToolDisplayContent(toolResult) {
  const isSuccess = !toolResult.isError && !toolResult.error;
  if (!isSuccess) return null;

  try {
    const content =
      typeof toolResult.content === 'string' ? JSON.parse(toolResult.content) : toolResult.content;
    if (content && typeof content.display === 'string' && content.display.trim().length > 0) {
      return content.display;
    }
  } catch (e) {
    // Not valid JSON or no display
  }
  return null;
}

/**
 * Extracts the content summary string from a tool result (for AI context).
 * @param {object} toolResult - The tool result object
 * @returns {string|null} The content summary or null if not found
 */
export function getToolContentSummary(toolResult) {
  try {
    const parsed =
      typeof toolResult.content === 'string' ? JSON.parse(toolResult.content) : toolResult.content;
    if (parsed && typeof parsed.content === 'string') {
      return parsed.content;
    }
  } catch (e) {
    // Not valid JSON - return raw content if it's a string
    if (typeof toolResult.content === 'string') {
      return toolResult.content;
    }
  }
  return null;
}

/**
 * Format a tool call result as rich HTML with status icons
 * @param {Object} toolResult - The tool result object/message
 * @param {string} toolName - The name of the tool (must be provided as it might not be in the message)
 * @param {string} [preRenderedContent=null] - Optional pre-rendered HTML content to use instead of raw extraction
 * @param {string} [justification=''] - Optional justification for why the tool was used
 * @returns {string} HTML string for display
 */
export function formatToolCallDisplay(
  toolResult,
  toolName = null,
  preRenderedContent = null,
  justification = ''
) {
  let isSuccess = !toolResult.isError && !toolResult.error;

  // Enhance success detection by checking content for error signatures
  // (BaseTool returns success:false in content but doesn't set isError on the message object)
  if (isSuccess && typeof toolResult.content === 'string') {
    try {
      if (
        toolResult.content.includes('"success":false') ||
        toolResult.content.includes('"error":')
      ) {
        const parsed = JSON.parse(toolResult.content);
        if (parsed && (parsed.success === false || parsed.error)) {
          isSuccess = false;
        }
      }
    } catch (e) {}
  }

  const statusClass = isSuccess ? 'tool-success' : 'tool-failure';
  const iconClass = isSuccess ? 'fa-solid fa-circle-check' : 'fa-solid fa-triangle-exclamation';

  // Build action text from tool name
  const effectiveToolName = toolName || toolResult.toolName || 'unknown';
  const actionText = getToolActionText(effectiveToolName, toolResult);

  // Build justification HTML if provided
  const justificationHtml = justification
    ? `<div class="tool-justification"><p>${justification}</p></div>`
    : '';

  // Specialized Macro Result Display
  let resultHtml = '';
  if (effectiveToolName === 'execute_macro' && isSuccess) {
    resultHtml = formatMacroResult(toolResult);
  }
  if (!resultHtml) {
    // Standard display logic (handles both success and error)
    if (preRenderedContent && isSuccess) {
      resultHtml = `<div class="tool-result-display">${preRenderedContent}</div>`;
    } else {
      // Generic tool result display (supports error display extraction)
      resultHtml = extractToolDisplay(toolResult);
    }
  }

  // Only show document info if there's no result display (avoids redundancy)
  let documentHtml = '';
  if (!resultHtml) {
    const documentInfo = extractDocumentInfo(toolResult);
    documentHtml = documentInfo ? `<span class="tool-document">${documentInfo}</span>` : '';
  }

  return `<div class="simulacrum-tool-call ${statusClass}"><i class="${iconClass} tool-icon"></i><span class="tool-action">${actionText}</span>${justificationHtml}${documentHtml}${resultHtml}</div>`;
}

/**
 * Format a pending tool call as HTML with spinner icon
 * @param {string} toolName - The name of the tool being executed
 * @param {string} [justification=''] - Optional justification/reason for the tool call
 * @param {string} [toolCallId=''] - The tool call ID for tracking
 * @returns {string} HTML string for pending tool card display
 */
export function formatPendingToolCall(toolName, justification = '', toolCallId = '') {
  // Try to get localized tool name from en.json
  const locKey = `SIMULACRUM.Tools.${toolName}`;
  let actionText = game.i18n.localize(locKey);

  // If localization key not found, fall back to formatting the tool name
  if (actionText === locKey) {
    actionText = toolName.replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  const justificationHtml = justification
    ? `<div class="tool-justification"><p>${justification}</p></div>`
    : '';

  const dataAttr = toolCallId ? ` data-tool-call-id="${toolCallId}"` : '';

  return `<div class="simulacrum-tool-call tool-pending"${dataAttr}><i class="fa-solid fa-circle-notch fa-spin tool-icon"></i><span class="tool-action">${actionText}</span>${justificationHtml}</div>`;
}

/**
 * Get human-readable action text for a tool
 * @param {string} toolName - The tool name
 * @param {Object} toolResult - The tool result for context
 * @returns {string} Human-readable action text
 */
export function getToolActionText(toolName, toolResult) {
  // Try to get localized tool name from en.json
  const locKey = `SIMULACRUM.Tools.${toolName}`;
  let action = game.i18n.localize(locKey);

  // If localization key not found, game.i18n.localize returns the key itself
  // In that case, fall back to formatting the tool name
  if (action === locKey) {
    action = toolName.replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  }

  const docType = toolResult.documentType || '';
  return docType ? `${action}: ${docType}` : action;
}

/**
 * Extract document name/info from tool result for display
 * @param {Object} toolResult - The tool result
 * @returns {string|null} Document info or null
 */
export function extractDocumentInfo(toolResult) {
  // Try to extract document name from the result content
  const content = String(toolResult.content || '');

  // Look for document name patterns
  const nameMatch = content.match(/"name":\s*"([^"]+)"/);
  if (nameMatch) {
    return nameMatch[1];
  }

  // Look for "Created X" or similar success messages
  const createdMatch = content.match(
    /(?:Created|Updated|Deleted|Read)\s+(\w+)\s+(?:document\s+)?['"]([^'"]+)['"]/i
  );
  if (createdMatch) {
    return createdMatch[2];
  }

  // Look for Macro execution message
  const macroMatch = content.match(/executed macro:\s*([^"'}]+)/i);
  if (macroMatch) {
    return macroMatch[1].trim();
  }

  return null;
}

/**
 * Format macro execution result
 * @param {Object} toolResult
 * @returns {string} HTML string
 */
// eslint-disable-next-line complexity
export function formatMacroResult(toolResult) {
  try {
    // Content is JSON stringified result from tool
    let contentObj;
    try {
      contentObj = JSON.parse(toolResult.content);
    } catch {
      // content might not be json
      return '';
    }

    let macroResult = contentObj;

    // Loop to unwrap nested JSON strings (max 3 levels to avoid infinite loops)
    for (let i = 0; i < 3; i++) {
      if (typeof macroResult === 'string') {
        try {
          const parsed = JSON.parse(macroResult);
          if (parsed && typeof parsed === 'object') {
            macroResult = parsed;
          } else {
            break;
          }
        } catch {
          break;
        }
        // eslint-disable-next-line max-depth
      } else {
        break;
      }
    }

    if (macroResult && macroResult.result && macroResult.result.total !== undefined) {
      let html = `<div class="tool-result"><strong>Roll Result:</strong> ${macroResult.result.total}</div>`;
      if (macroResult.result.formula) {
        html += `<div class="tool-result-detail"><small>Formula: ${macroResult.result.formula}</small></div>`;
      }
      return html;
    } else if (macroResult && macroResult.result !== undefined) {
      const resultStr =
        typeof macroResult.result === 'object'
          ? JSON.stringify(macroResult.result, null, 2)
          : String(macroResult.result);
      return `<div class="tool-result"><strong>Result:</strong> ${resultStr}</div>`;
    }
  } catch (e) {
    /* ignore parse errors */
  }
  return '';
}

/**
 * Extract generic display content from tool result if available
 * @param {Object} toolResult
 * @returns {string} HTML string
 */
export function extractToolDisplay(toolResult) {
  try {
    const content = toolResult.content || '';
    // Check if content is a JSON string
    if (typeof content === 'string' && content.startsWith('{')) {
      const parsed = JSON.parse(content);

      if (parsed && typeof parsed === 'object') {
        // Case 1: Error object (check before display — errors also have display)
        if (parsed.error && (parsed.error.message || typeof parsed.error === 'string')) {
          const errorMessage = parsed.error.message || parsed.error;
          const errorType = parsed.error.type ? `<strong>${parsed.error.type}:</strong> ` : '';
          return `<div class="tool-result-display error-display">${errorType}${errorMessage}</div>`;
        }

        // Case 2: Display property exists (standard success)
        if (parsed.display) {
          return `<div class="tool-result-display">${parsed.display}</div>`;
        }

        // Case 3: Success but no display (message property)
        if (parsed.message) {
          return `<div class="tool-result-display">${parsed.message}</div>`;
        }

        // Case 4: Compacted output
        if (parsed._compacted) {
          // If display was preserved during compaction, use it for formatted rendering
          if (parsed.display) {
            return `<div class="tool-result-display">${parsed.display}</div>`;
          }
          // Otherwise show compacted info with preview
          return `<div class="tool-result-display compacted-display">
            <div class="compacted-header"><i class="fas fa-compress-alt"></i> Output Compacted</div>
            <div class="compacted-info">
              Total: ${parsed.total_lines} lines (${parsed.total_chars} chars)<br>
              <em>${parsed.access}</em>
            </div>
            ${parsed.preview ? `<div class="compacted-preview"><pre>${parsed.preview}</pre></div>` : ''}
          </div>`;
        }
      }
    }
  } catch (e) {
    /* ignore */
  }
  return '';
}

/**
 * Group consecutive messages from the same role (specifically assistant)
 * @param {Array<Object>} messages - Array of message objects
 * @returns {Array<Object>} Grouped messages
 */
export function groupConsecutiveMessages(messages) {
  if (!messages || messages.length === 0) return [];

  const grouped = [];
  let currentGroup = null;

  for (const msg of messages) {
    // Only group 'assistant' messages for now, as requested
    if (msg.role === 'assistant') {
      if (currentGroup && currentGroup.role === 'assistant') {
        // Merge into current group
        // 1. Calculate new display BEFORE mutating content (Fix for JSON leak)
        // Ensure we handle cases where display might be missing (fallback to content)
        const currentDisplay = currentGroup.display || currentGroup.content;
        const newDisplay = msg.display || msg.content;

        // 2. Combine content (with newline)
        currentGroup.content += '\n\n' + msg.content;

        // 3. Set combined display
        currentGroup.display = currentDisplay + newDisplay;
        // 3. Keep original timestamp/id of the group starter
      } else {
        // Start a new assistant group
        // Clone to avoid mutating original if needed, though mostly safe here
        currentGroup = { ...msg };
        grouped.push(currentGroup);
      }
    } else {
      // Non-assistant message: push and reset group
      grouped.push(msg);
      currentGroup = null;
    }
  }

  return grouped;
}

/**
 * A utility class to manage a queue of async tasks, ensuring they execute sequentially.
 * Useful for preventing race conditions in UI updates (e.g., chat streaming).
 */
export class SequentialQueue {
  constructor() {
    this.queue = Promise.resolve();
  }

  /**
   * Add a task to the queue.
   * @param {Function} task - A function that returns a Promise (or is sync).
   * @returns {Promise<any>} - Resolves with the result of the task.
   */
  add(task) {
    // Chain the new task to the end of the existing queue
    const next = this.queue
      .then(() => task())
      .catch(err => {
        console.error('SequentialQueue task failed:', err);
        // We catch here to ensure the queue chain isn't broken for subsequent tasks
        throw err;
      });

    // Update the queue pointer, but catch errors to keep the chain valid for the *next* add() call
    // (The checking above propagates the error to the caller of .add())
    this.queue = next.catch(() => {});

    return next;
  }
}

import { SchemaValidator } from './schema-validator.js';
import { createLogger } from './logger.js';

const logger = createLogger('ValidationErrorHandler');

/**
 * Validation Error Handler - Unified handling for Foundry validation errors
 * Converts Foundry's DataModelValidationError into AI-friendly structured feedback
 */

export class ValidationErrorHandler {
  /**
   * Parse a Foundry DataModelValidationError into structured feedback
   * @param {Error} error - The error to parse
   * @returns {Object|null} Structured validation error details or null if not a validation error
   */
  static parseFoundryValidationError(error) {
    // Check for DataModelValidationError by name
    const isDataModelValidationError = error.name === 'DataModelValidationError';

    // Also check for validation errors by message pattern (some systems wrap errors)
    const hasValidationPattern =
      error.message &&
      (error.message.includes('validation errors:') ||
        error.message.includes('Validation failed') ||
        error.message.includes('validation failed'));

    // Check for Foundry's getAllFailures method (definitive sign of validation error)
    const hasGetAllFailures = error.getAllFailures && typeof error.getAllFailures === 'function';

    if (!isDataModelValidationError && !hasValidationPattern && !hasGetAllFailures) {
      return null;
    }

    // Use FoundryVTT's official getAllFailures() method if available
    let validationDetails = {};
    if (error.getAllFailures && typeof error.getAllFailures === 'function') {
      try {
        const allFailures = error.getAllFailures();
        validationDetails = this.processFoundryFailures(allFailures);
      } catch (e) {
        logger.warn('Failed to use getAllFailures(), falling back to message parsing');
        validationDetails = this.extractValidationDetails(error);
      }
    } else {
      // Fallback to message parsing for older versions or edge cases
      validationDetails = this.extractValidationDetails(error);
    }

    const suggestions = this.generateSuggestions(validationDetails);

    return {
      type: 'VALIDATION_ERROR',
      message: error.message,
      originalError: error,
      details: validationDetails,
      suggestions,
      aiContext: this.createAIContext(validationDetails, suggestions),
    };
  }

  /**
   * Process validation failures using FoundryVTT's official getAllFailures() method
   * @param {Object} allFailures - Result from error.getAllFailures()
   * @returns {Object} Structured validation details
   */
  static processFoundryFailures(allFailures) {
    const details = {};

    for (const [fieldPath, failure] of Object.entries(allFailures)) {
      details[fieldPath] = {
        field: fieldPath,
        error: failure.message || 'Validation failed',
        invalidValue: failure.invalidValue,
        fallback: failure.fallback,
        dropped: failure.dropped || false,
      };
    }

    return details;
  }

  /**
   * Extract structured validation details from Foundry error (fallback method)
   * @param {Error} error - DataModelValidationError
   * @returns {Object} Structured validation details
   */
  static extractValidationDetails(error) {
    const details = {};

    // Parse error message to extract field-specific validation failures
    // Foundry format: "Document [id] validation errors:\n  field: error message"
    const errorMessage = error.message || '';
    const lines = errorMessage.split('\n');

    let currentPath = '';
    for (const line of lines) {
      const trimmed = line.trim();

      // Skip header lines
      if (trimmed.includes('validation errors:') || trimmed === '') {
        continue;
      }

      // Handle nested field paths (indented lines)
      const indentLevel = line.length - line.trimStart().length;

      if (trimmed.includes(':')) {
        const [fieldPart, ...messageParts] = trimmed.split(':');
        const field = fieldPart.trim();
        const message = messageParts.join(':').trim();

        // Build full field path
        if (indentLevel === 0) {
          currentPath = field;
        } else {
          currentPath = currentPath ? `${currentPath}.${field}` : field;
        }

        details[currentPath] = {
          field: currentPath,
          error: message,
          indentLevel,
        };
      }
    }

    return details;
  }

  /**
   * Generate AI-friendly suggestions based on validation errors
   * @param {Object} validationDetails - Structured validation details
   * @returns {Array} Array of suggestion objects
   */
  static generateSuggestions(validationDetails) {
    const suggestions = [];

    for (const [fieldPath, detail] of Object.entries(validationDetails)) {
      const suggestion = this.createFieldSuggestion(fieldPath, detail);
      if (suggestion) {
        suggestions.push(suggestion);
      }
    }

    return suggestions;
  }

  /**
   * Create a suggestion for a specific field validation error
   * @param {string} fieldPath - The field path (e.g., "pages.oEiIxE7ZVA1HTl0X.name")
   * @param {Object} detail - The validation detail
   * @returns {Object} Suggestion object
   */
  // eslint-disable-next-line complexity
  static createFieldSuggestion(fieldPath, detail) {
    const { error, invalidValue, fallback } = detail;
    const suggestion = {
      field: fieldPath,
      issue: error,
      action: null,
      example: null,
      invalidValue: invalidValue,
      suggestedValue: fallback,
    };

    // Enhanced validation error patterns and suggestions
    if (error.includes('may not be undefined') || error.includes('is required')) {
      suggestion.action = `Provide a value for required field "${fieldPath}"`;
      suggestion.example = fallback || this.getFieldExample(fieldPath);
    } else if (error.includes('must be a valid 16-character alphanumeric ID')) {
      suggestion.action = `Use foundry.utils.randomID() to generate a valid ID for "${fieldPath}"`;
      suggestion.example = 'foundry.utils.randomID()';
    } else if (error.includes('must be') && error.includes('type')) {
      suggestion.action = `Ensure field "${fieldPath}" has the correct data type`;
      suggestion.example = fallback || this.getTypeExample(error);
    } else if (error.includes('is not a valid choice')) {
      suggestion.action = `Use a valid choice for field "${fieldPath}"`;
      if (fallback !== undefined) {
        suggestion.example = fallback;
      }
    } else if (error.includes('invalid')) {
      suggestion.action = `Check that the value for "${fieldPath}" is valid`;
      if (invalidValue !== undefined) {
        suggestion.action += ` (received: ${JSON.stringify(invalidValue)})`;
      }
    } else {
      suggestion.action = `Fix validation error for field "${fieldPath}": ${error}`;
    }

    return suggestion;
  }

  /**
   * Get example value for a field based on its path
   * @param {string} fieldPath - The field path
   * @returns {string} Example value
   */
  static getFieldExample(fieldPath) {
    const lowerPath = fieldPath.toLowerCase();

    if (lowerPath.includes('name')) {
      return '"Example Name"';
    } else if (lowerPath.includes('type')) {
      return '"text"';
    } else if (lowerPath.includes('content')) {
      return '"<p>Example content</p>"';
    } else if (lowerPath.includes('title')) {
      return '"Example Title"';
    } else if (lowerPath.includes('img') || lowerPath.includes('image')) {
      return '"icons/example.png"';
    } else {
      return '"example_value"';
    }
  }

  /**
   * Get example for a specific type error
   * @param {string} error - The type error message
   * @returns {string} Type example
   */
  static getTypeExample(error) {
    if (error.includes('string')) {
      return '"string_value"';
    } else if (error.includes('number')) {
      return '42';
    } else if (error.includes('boolean')) {
      return 'true';
    } else if (error.includes('array')) {
      return '[]';
    } else if (error.includes('object')) {
      return '{}';
    } else {
      return '"example_value"';
    }
  }

  /**
   * Create AI-friendly context message for validation errors
   * @param {Object} validationDetails - Structured validation details
   * @param {Array} suggestions - Generated suggestions
   * @returns {string} AI context message
   */
  static createAIContext(validationDetails, suggestions) {
    const fieldCount = Object.keys(validationDetails).length;

    // Create detailed field-by-field guidance
    const fieldGuidance = suggestions
      .map(s => {
        let guidance = `- ${s.field}: ${s.action}`;
        if (s.example) {
          guidance += ` (example: ${s.example})`;
        }
        if (s.suggestedValue !== undefined) {
          guidance += ` (suggested: ${JSON.stringify(s.suggestedValue)})`;
        }
        return guidance;
      })
      .join('\n');

    // Add specific instructions for common FoundryVTT patterns
    let instructions = '';
    const hasIdErrors = suggestions.some(s => s.issue.includes('16-character alphanumeric'));
    const hasRequiredErrors = suggestions.some(
      s => s.issue.includes('required') || s.issue.includes('undefined')
    );
    const hasChoiceErrors = suggestions.some(s => s.issue.includes('not a valid choice'));

    if (hasIdErrors) {
      instructions +=
        '\nFor ID fields: Use foundry.utils.randomID() to generate valid 16-character alphanumeric IDs.';
    }
    if (hasRequiredErrors) {
      instructions += '\nFor required fields: Ensure all mandatory fields have non-empty values.';
    }
    if (hasChoiceErrors) {
      instructions += '\nFor choice fields: Check field schema for valid enum values.';
    }

    return `FoundryVTT validation failed on ${fieldCount} field(s). Required fixes:\n${fieldGuidance}${instructions}\n\nPlease retry with corrected field values.`;
  }

  /**
   * Create a comprehensive error response for tools
   * @param {Error} error - The original error
   * @param {string} operation - The operation that failed (e.g., "create", "update")
   * @param {string} documentType - The document type
   * @param {string} documentId - The document ID (for updates)
   * @returns {Object} Tool error response
   */
  static createToolErrorResponse(error, operation, documentType, documentId = null) {
    const validationError = this.parseFoundryValidationError(error);

    if (validationError) {
      const docRef = documentId ? `@UUID[${documentType}.${documentId}]` : documentType;

      // Enhance suggestions with schema-aware analysis
      const enhancedSuggestions = this.enhanceWithSchemaAnalysis(
        validationError.suggestions,
        documentType
      );

      // Create enhanced AI context with schema information
      const enhancedContext = this.createEnhancedAIContext(
        validationError.details,
        enhancedSuggestions,
        documentType
      );

      return {
        content: `Validation failed for ${operation} ${docRef}: ${enhancedContext}`,
        display: `Validation Error: ${validationError.message}`,
        error: {
          message: validationError.message,
          type: 'VALIDATION_ERROR',
          details: validationError.details,
          suggestions: enhancedSuggestions,
          aiContext: enhancedContext,
          documentType: documentType,
          operation: operation,
        },
      };
    }

    // Fallback for non-validation errors
    const docRef = documentId ? `@UUID[${documentType}.${documentId}]` : documentType;
    return {
      content: `Failed to ${operation} ${docRef}: ${error.message}`,
      display: `Failed to ${operation} ${docRef}: ${error.message}`,
      error: {
        message: error.message,
        type: `${operation.toUpperCase()}_FAILED`,
      },
    };
  }

  /**
   * Enhance suggestions with schema-aware analysis
   * @param {Array} suggestions - Original suggestions
   * @param {string} documentType - The document type
   * @returns {Array} Enhanced suggestions
   */
  static enhanceWithSchemaAnalysis(suggestions, documentType) {
    return suggestions.map(suggestion => {
      const schemaSuggestion = SchemaValidator.getFieldSuggestion(
        documentType,
        suggestion.field,
        suggestion.issue,
        suggestion.invalidValue
      );

      return {
        ...suggestion,
        schemaAnalysis: schemaSuggestion,
        correctionMethod: schemaSuggestion.correctionMethod || suggestion.action,
        schemaExample: schemaSuggestion.example || suggestion.example,
      };
    });
  }

  /**
   * Create enhanced AI context with schema information
   * @param {Object} validationDetails - Validation details
   * @param {Array} enhancedSuggestions - Schema-enhanced suggestions
   * @param {string} documentType - The document type
   * @returns {string} Enhanced AI context
   */
  static createEnhancedAIContext(validationDetails, enhancedSuggestions, documentType) {
    const fieldCount = Object.keys(validationDetails).length;

    // Create detailed field-by-field guidance with schema information
    const fieldGuidance = enhancedSuggestions
      .map(s => {
        let guidance = `- ${s.field}: ${s.correctionMethod || s.action}`;

        if (s.schemaExample) {
          guidance += ` (use: ${s.schemaExample})`;
        } else if (s.example) {
          guidance += ` (example: ${s.example})`;
        }

        if (s.schemaAnalysis?.fieldType) {
          guidance += ` [${s.schemaAnalysis.fieldType}]`;
        }

        return guidance;
      })
      .join('\n');

    // Add document-type specific instructions
    const instructions = this.getDocumentTypeInstructions(documentType, enhancedSuggestions);

    // Include schema reference to help AI self-correct
    const schemaRef = this.getSchemaReference(documentType);

    return `FoundryVTT ${documentType} validation failed on ${fieldCount} field(s). Required fixes:\n${fieldGuidance}${instructions}${schemaRef}\n\nPlease retry with corrected field values.`;
  }

  /**
   * Get a compact schema reference for error context
   * @param {string} documentType - The document type
   * @returns {string} Schema reference string
   */
  static getSchemaReference(documentType) {
    try {
      const schemaInfo = SchemaValidator.getDocumentSchema(documentType);
      if (!schemaInfo || !schemaInfo.fields) return '';

      const fields = Object.keys(schemaInfo.fields);
      const topLevelFields = fields.slice(0, 15); // Limit to avoid huge output
      const hasMore = fields.length > 15;

      let ref = `\n\n--- ${documentType} Schema Reference ---\n`;
      ref += `Top-level fields: ${topLevelFields.join(', ')}${hasMore ? '...' : ''}\n`;

      // Include embedded document hints
      const embeddedFields = fields.filter(f => {
        const fieldInfo = schemaInfo.fields[f];
        return fieldInfo?.type === 'EmbeddedCollectionField';
      });
      if (embeddedFields.length > 0) {
        ref += `Embedded collections: ${embeddedFields.join(', ')}\n`;
      }

      return ref;
    } catch (e) {
      return '';
    }
  }

  /**
   * Get document-type specific instructions
   * @param {string} documentType - The document type
   * @param {Array} suggestions - Enhanced suggestions
   * @returns {string} Type-specific instructions
   */
  static getDocumentTypeInstructions(documentType, suggestions) {
    let instructions = '';

    // Common FoundryVTT patterns
    const hasIdErrors = suggestions.some(s => s.issue.includes('16-character alphanumeric'));
    const hasRequiredErrors = suggestions.some(
      s => s.issue.includes('required') || s.issue.includes('undefined')
    );
    const hasChoiceErrors = suggestions.some(s => s.issue.includes('not a valid choice'));

    if (hasIdErrors) {
      instructions +=
        '\n• For ID fields: Use foundry.utils.randomID() to generate valid 16-character alphanumeric IDs.';
    }
    if (hasRequiredErrors) {
      instructions += '\n• For required fields: Ensure all mandatory fields have non-empty values.';
    }
    if (hasChoiceErrors) {
      instructions +=
        '\n• For choice fields: Use inspect_document_schema to discover valid enum values.';
    }

    // Dynamic hints based on error patterns (no hardcoded document types)
    if (
      suggestions.some(
        s => s.field.includes('pages') || s.field.includes('items') || s.field.includes('effects')
      )
    ) {
      instructions +=
        '\n• For embedded documents: Each entry needs name, type, and appropriate content fields. Use inspect_document_schema to see the structure.';
    }
    if (suggestions.some(s => s.issue.includes('type') || s.field === 'type')) {
      instructions +=
        '\n• For type fields: Use inspect_document_schema to discover valid subtypes for this document.';
    }

    return instructions;
  }
}

#!/usr/bin/env node
/**
 * Build packs using the official Foundry VTT CLI.
 * This ensures LevelDB files are in the exact format Foundry expects.
 *
 * Macro scripts: If a .json source file has a matching .js file (same basename),
 * the .js content is injected into the JSON's `command` field at build time.
 * This keeps macro scripts maintainable as standalone JS files.
 */
import { execSync } from 'child_process';
import { existsSync, rmSync, readdirSync, readFileSync, writeFileSync, mkdirSync, cpSync } from 'fs';
import { join, dirname, basename, extname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');

// Pack definitions: [sourceName, outputName]
const PACKS = [
    ['simulacrum-tools', 'simulacrum-tools']
];

/**
 * Prepare a staging directory with JS scripts injected into JSON command fields.
 * @param {string} sourceDir - Path to the _source directory for this pack
 * @returns {string} Path to the staging directory (caller must clean up)
 */
function prepareStaging(sourceDir) {
    const stagingDir = join(ROOT, 'packs', '_staging');
    if (existsSync(stagingDir)) rmSync(stagingDir, { recursive: true, force: true });
    mkdirSync(stagingDir, { recursive: true });

    // Copy all JSON files and inject matching JS scripts
    const files = readdirSync(sourceDir);
    const jsonFiles = files.filter(f => extname(f) === '.json');

    for (const jsonFile of jsonFiles) {
        const doc = JSON.parse(readFileSync(join(sourceDir, jsonFile), 'utf-8'));
        const jsFile = basename(jsonFile, '.json') + '.js';

        if (files.includes(jsFile)) {
            const script = readFileSync(join(sourceDir, jsFile), 'utf-8');
            doc.command = script;
            console.log(`  Injected ${jsFile} -> ${jsonFile}`);
        }

        writeFileSync(join(stagingDir, jsonFile), JSON.stringify(doc, null, 4) + '\n');
    }

    return stagingDir;
}

async function build() {
    for (const [sourceName, outputName] of PACKS) {
        const sourceDir = join(ROOT, 'packs', '_source', sourceName);
        const outputDir = join(ROOT, 'packs', outputName);

        if (!existsSync(sourceDir)) {
            console.log(`Skipping ${sourceName}: source directory not found`);
            continue;
        }

        // Clean output directory
        if (existsSync(outputDir)) {
            rmSync(outputDir, { recursive: true, force: true });
        }

        console.log(`Building pack: ${sourceName} -> ${outputName}`);

        // Prepare staging with injected scripts
        const stagingDir = prepareStaging(sourceDir);

        // Use official Foundry CLI
        const cmd = `npx fvtt package pack --type Module --id simulacrum -n ${outputName} --in "${stagingDir}" --out "${join(ROOT, 'packs')}" -v`;

        try {
            const result = execSync(cmd, {
                cwd: ROOT,
                encoding: 'utf-8',
                stdio: ['pipe', 'pipe', 'pipe']
            });
            console.log(result);
        } catch (err) {
            console.error(`Failed to build ${sourceName}:`, err.message);
            if (err.stderr) console.error(err.stderr);
            process.exit(1);
        } finally {
            // Clean up staging
            rmSync(stagingDir, { recursive: true, force: true });
        }
    }

    console.log('All packs built successfully.');
}

build().catch(err => {
    console.error(err);
    process.exit(1);
});

